"""Where the application keeps its data: a PostgreSQL target and one namespace.

Owned by the database adapter so adapters never import the top-level settings; `Settings`
only aggregates this value with the other sections.
"""

import re
from dataclasses import dataclass, field

from sqlalchemy.engine import URL, make_url


@dataclass(frozen=True, slots=True)
class DatabaseSettings:
    url: str = field(repr=False)
    schema: str = "caliburn"

    def __post_init__(self) -> None:
        if not re.fullmatch(r"[a-z][a-z0-9_]{0,62}", self.schema):
            raise ValueError("Database schema must be a lowercase PostgreSQL identifier")
        if make_url(self.url).drivername not in {"postgresql", "postgresql+psycopg"}:
            raise ValueError("The target database must use PostgreSQL with psycopg")

    @property
    def sqlalchemy_url(self) -> URL:
        return make_url(self.url).set(drivername="postgresql+psycopg")

apps/api/src/caliburn/adapters/openai_cr:
"""Read only an explicitly selected direct OpenAI credential; never load legacy settings."""

import re
from pathlib import Path


def read_openai_api_key(path: Path) -> str:
    values = []
    for line in path.read_text(encoding="utf-8-sig").splitlines():
        name, separator, value = line.strip().partition("=")
        if separator and name.strip() == "OPENAI_API_KEY":
            value = value.strip()
            if len(value) >= 2 and value[0] == value[-1] and value[0] in "\"'":
                value = value[1:-1]
            values.append(value)
    if len(values) != 1 or not re.fullmatch(r"[A-Za-z0-9_-]+", values[0]):
        raise ValueError("Exactly one plain OPENAI_API_KEY value is required")
    return values[0]

apps/api/src/caliburn/adapters/openai_fa:
"""Safe provider failure classification, not authorization to retry or a billing verdict."""

from dataclasses import dataclass
from enum import StrEnum

from openai import APIConnectionError, APIError, APIResponseValidationError, APIStatusError

_BLOCKED_CODES = frozenset(
    {
        "credit_balance_exhausted",
        "organization_spend_limit_exceeded",
        "project_spend_limit_exceeded",
        "organization_usage_limit_exceeded",
        "insufficient_quota",
    }
)
# An error event inside an open HTTP 200 stream has no status, so only its code can say that
# it is a provider hiccup or a rate limit. Anything not named here stays a terminal failure.
_RATE_LIMIT_CODES = frozenset({"rate_limit_exceeded", "slow_down"})
_TRANSIENT_STREAM_CODES = frozenset({"server_error", "server_is_overloaded", "service_unavailable"})
_DIAGNOSTIC_CODES = (
    _BLOCKED_CODES
    | _RATE_LIMIT_CODES
    | _TRANSIENT_STREAM_CODES
    | {
        "context_length_exceeded",
        "invalid_api_key",
    }
)


class ResponseFailureKind(StrEnum):
    REMOTE_RESULT_UNKNOWN = "remote_result_unknown"
    TRANSIENT_SERVICE = "transient_service"
    # The provider asking us to slow down is waiting, not a fault of the work; see the retry policy.
    RATE_LIMITED = "rate_limited"
    ACCESS_BLOCKED = "access_blocked"
    CAPACITY_EXCEEDED = "capacity_exceeded"
    REQUEST_REJECTED = "request_rejected"
    RESPONSE_PROTOCOL = "response_protocol"


@dataclass(frozen=True, slots=True)
class ResponseFailure:
    kind: ResponseFailureKind
    status_code: int | None = None
    provider_code: str | None = None


def classify_response_failure(error: APIError) -> ResponseFailure:
    """Never copy exception text/body, which may contain input or credentials, into State/UI.

    Transient only describes the cause. A subsequent request still requires original-result
    reconciliation, Retry-After handling and fresh admission against the original work budget.
    None of these outcomes establishes that the failed request was free.
    """
    if isinstance(error, APIConnectionError):
        return ResponseFailure(ResponseFailureKind.REMOTE_RESULT_UNKNOWN)
    if isinstance(error, APIResponseValidationError):
        return ResponseFailure(ResponseFailureKind.RESPONSE_PROTOCOL, error.status_code)
    status = error.status_code if isinstance(error, APIStatusError) else None
    if status in (401, 403) or error.code in _BLOCKED_CODES or error.type == "insufficient_quota":
        kind = ResponseFailureKind.ACCESS_BLOCKED
    elif error.code == "context_length_exceeded":
        kind = ResponseFailureKind.CAPACITY_EXCEEDED
    elif not isinstance(error, APIStatusError):
        if error.code in _RATE_LIMIT_CODES:
            kind = ResponseFailureKind.RATE_LIMITED
        elif error.code in _TRANSIENT_STREAM_CODES:
            kind = ResponseFailureKind.TRANSIENT_SERVICE
        else:
            kind = ResponseFailureKind.RESPONSE_PROTOCOL
    elif error.response.headers.get("x-should-retry") == "false":
        kind = ResponseFailureKind.REQUEST_REJECTED
    elif error.status_code == 429:
        kind = ResponseFailureKind.RATE_LIMITED
    elif error.status_code in (408, 409) or error.status_code >= 500:
        kind = ResponseFailureKind.TRANSIENT_SERVICE
    else:
        kind = ResponseFailureKind.REQUEST_REJECTED
    # Codes are external strings too. Retain only known constants, never an echoed payload.
    provider_code = error.code if error.code in _DIAGNOSTIC_CODES else None
    return ResponseFailure(kind, status, provider_code)

apps/api/src/caliburn/adapters/reasoning:
"""Allowlisted readable summaries, never raw reasoning or encrypted continuation state."""

import logging
from collections.abc import Callable
from dataclasses import dataclass, field

from openai.types.responses import Response, ResponseReasoningItem, ResponseStreamEvent

_LOG = logging.getLogger(__name__)


@dataclass(frozen=True, slots=True)
class PublicReasoningSummary:
    response_id: str
    item_id: str
    output_index: int
    summary_index: int
    text: str = field(repr=False)


def project_reasoning_summaries(response: Response) -> tuple[PublicReasoningSummary, ...]:
    if response.status != "completed" or response.error is not None:
        return ()
    return tuple(
        PublicReasoningSummary(response.id, item.id, output_index, summary_index, part.text)
        for output_index, item in enumerate(response.output)
        if isinstance(item, ResponseReasoningItem) and item.status in (None, "completed")
        for summary_index, part in enumerate(item.summary)
        if part.type == "summary_text" and part.text.strip()
    )


class ReasoningSummaryProjection:
    """Accumulate text per native part; done events replace deltas rather than append."""

    def __init__(self, callback: Callable[[PublicReasoningSummary], None] | None) -> None:
        self.callback = callback
        self.response_id: str | None = None
        self.items: dict[str, int] = {}
        self.parts: dict[tuple[str, int], str] = {}
        self.emitted: dict[tuple[str, int], str] = {}

    def accept(self, event: ResponseStreamEvent) -> None:
        if self.callback is None:
            return
        if event.type == "response.created":
            self.response_id = event.response.id
        elif event.type in ("response.output_item.added", "response.output_item.done"):
            item = event.item
            if not isinstance(item, ResponseReasoningItem):
                return
            self.items[item.id] = event.output_index
            for index, part in enumerate(item.summary):
                if part.type == "summary_text":
                    self._replace(item.id, index, part.text)
        elif event.type in (
            "response.reasoning_summary_text.delta",
            "response.reasoning_summary_text.done",
            "response.reasoning_summary_part.added",
            "response.reasoning_summary_part.done",
        ):
            if self.items.get(event.item_id) != event.output_index:
                return
            key = (event.item_id, event.summary_index)
            if event.type == "response.reasoning_summary_text.delta":
                text = self.parts.get(key, "") + event.delta
            elif event.type == "response.reasoning_summary_text.done":
                text = event.text
            else:
                if event.part.type != "summary_text":
                    return
                text = event.part.text
            self._replace(event.item_id, event.summary_index, text)

    def _replace(self, item_id: str, summary_index: int, text: str) -> None:
        key = (item_id, summary_index)
        self.parts[key] = text
        if (
            self.response_id is None
            or self.callback is None
            or not text
            or self.emitted.get(key) == text
        ):
            return
        self.emitted[key] = text
        try:
            self.callback(
                PublicReasoningSummary(
                    self.response_id, item_id, self.items[item_id], summary_index, text
                )
            )
        except Exception:
            self.callback = None
            _LOG.warning("Public reasoning summary observer disabled after failure")

