"""Preserve provider originals separately from the supported outgoing item projection.

Any is confined to the SDK/JSON serialization boundary. No business state is inferred.
"""

from collections.abc import Sequence
from copy import deepcopy
from typing import Any

from openai.types.responses import Response, ResponseFunctionToolCall
from openai.types.responses.compacted_response import CompactedResponse
from openai.types.responses.response_input_item_param import FunctionCallOutput
from openai.types.responses.response_usage import ResponseUsage

type NativeSnapshot = dict[str, Any]
type NativeItems = list[dict[str, Any]]


def snapshot_response(response: Response) -> dict[str, Any]:
    """Capture every received field, preserving aliases and unknown provider metadata."""
    return response.model_dump(mode="json", by_alias=True, exclude_unset=True)


def restore_response(snapshot: dict[str, Any]) -> Response:
    """Validate executable content; preserve partial billing data with native SDK semantics."""
    usage = snapshot.get("usage")
    if isinstance(usage, dict):
        # SDK replies may omit billing details. Keep them absent, not fabricated as zero;
        # the pricing owner separately decides whether they support a cost estimate.
        snapshot = {**snapshot, "usage": ResponseUsage.model_construct(**usage)}
    return Response.model_validate(snapshot)


def response_input_items(response: Response) -> list[dict[str, Any]]:
    """Project whole output items, excluding only top-level output status per official example.

    The original snapshot still retains status. Remote acceptance is a separate provider gate.
    """
    return [
        item.model_dump(mode="json", by_alias=True, exclude_unset=True, exclude={"status"})
        for item in response.output
    ]


def snapshot_compaction(response: CompactedResponse) -> dict[str, Any]:
    """Capture the entire compaction result before Runtime adopts its complete output window."""
    # SDK output unions are narrower than retained inputs (e.g. user messages). Preserve
    # the received fields; avoid emitting schema warnings containing private input text.
    return response.to_dict(mode="json", warnings=False)


def compaction_input_items(snapshot: dict[str, Any]) -> list[dict[str, Any]]:
    """Return every compacted output item, including retained items, in original order."""
    output = snapshot.get("output")
    if not isinstance(output, list) or any(not isinstance(item, dict) for item in output):
        raise ValueError("The saved compaction result must contain a complete output window")
    return deepcopy(output)


def function_result_item(call: ResponseFunctionToolCall, output: str) -> FunctionCallOutput:
    """Pair one real tool result with its original direct call, never a generated call ID."""
    result: FunctionCallOutput = {
        "type": "function_call_output",
        "call_id": call.call_id,
        "output": output,
    }
    if call.caller is not None:
        if call.caller.type != "direct":
            raise ValueError("Only direct calls are supported by this result adapter")
        result["caller"] = {"type": "direct"}
    return result


def require_result_order(
    calls: Sequence[ResponseFunctionToolCall], results: Sequence[FunctionCallOutput]
) -> None:
    """A saved prefix may be incomplete, but cannot skip, duplicate or reorder calls."""
    if len(results) > len(calls):
        raise ValueError("There are more tool results than original calls")
    for call, result in zip(calls, results, strict=False):
        if result["type"] != "function_call_output" or result["call_id"] != call.call_id:
            raise ValueError("Tool results must follow the original call order")

"""Transient public text projection; native terminal responses remain the only originals."""

import logging
from asyncio import CancelledError
from collections.abc import Callable
from dataclasses import dataclass, field

from openai import APIConnectionError, AsyncStream
from openai.types.responses import Response, ResponseOutputMessage, ResponseStreamEvent

from caliburn.adapters.reasoning_summaries import PublicReasoningSummary, ReasoningSummaryProjection

_LOG = logging.getLogger(__name__)


@dataclass(frozen=True, slots=True)
class PublicCommentaryUpdate:
    response_id: str
    message_id: str
    text: str = field(repr=False)


class ResponseStreamCleanupError(RuntimeError):
    """A terminal original exists; reconcile it instead of repeating the provider call."""

    def __init__(self, response: Response) -> None:
        self.response = response
        super().__init__("Stream cleanup failed after receiving the original response")


class ResponseStreamCancelledError(CancelledError):
    """Propagate cancellation while handing the terminal original to the immediate caller."""

    def __init__(self, response: Response) -> None:
        self.response = response
        super().__init__("Stream cancelled after receiving the original response")


class ResponseStreamProtocolError(RuntimeError):
    """No terminal original was received; public text cannot substitute for one."""


class _CommentaryProjection:
    def __init__(self, callback: Callable[[PublicCommentaryUpdate], None] | None) -> None:
        self.callback = callback
        self.response_id: str | None = None
        self.messages: dict[str, int] = {}
        self.parts: dict[str, dict[int, str]] = {}
        self.emitted: dict[str, str] = {}

    def accept(self, event: ResponseStreamEvent) -> None:
        if self.callback is None:
            return
        if event.type == "response.created":
            self.response_id = event.response.id
        elif event.type in ("response.output_item.added", "response.output_item.done"):
            item = event.item
            if not (
                isinstance(item, ResponseOutputMessage)
                and item.role == "assistant"
                and item.phase == "commentary"
            ):
                return
            self.messages[item.id] = event.output_index
            self.parts[item.id] = {
                index: part.text if part.type == "output_text" else part.refusal
                for index, part in enumerate(item.content)
            }
            self._emit(item.id)
        elif event.type in (
            "response.output_text.delta",
            "response.output_text.done",
            "response.refusal.delta",
            "response.refusal.done",
        ):
            if self.messages.get(event.item_id) != event.output_index:
                return
            parts = self.parts[event.item_id]
            if event.type in ("response.output_text.delta", "response.refusal.delta"):
                parts[event.content_index] = parts.get(event.content_index, "") + event.delta
            elif event.type == "response.output_text.done":
                parts[event.content_index] = event.text
            elif event.type == "response.refusal.done":
                parts[event.content_index] = event.refusal
            self._emit(event.item_id)

    def _emit(self, message_id: str) -> None:
        if self.response_id is None or self.callback is None:
            return
        parts = self.parts[message_id]
        text = "\n\n".join(parts[index] for index in sorted(parts))
        if not text or self.emitted.get(message_id) == text:
            return
        self.emitted[message_id] = text
        try:
            self.callback(PublicCommentaryUpdate(self.response_id, message_id, text))
        except Exception:
            # Presentation is best effort. Never log observer text or exception payloads,
            # never await a slow reader, and never catch task cancellation here.
            self.callback = None
            _LOG.warning("Public commentary observer disabled after failure")


async def consume_response_stream(
    stream: AsyncStream[ResponseStreamEvent],
    *,
    on_commentary: Callable[[PublicCommentaryUpdate], None] | None = None,
    on_reasoning_summary: Callable[[PublicReasoningSummary], None] | None = None,
) -> Response:
    """Consume one SDK stream, preserving terminal R before any subsequent cleanup await.

    No delta assembly, automatic argument parsing, retry or durable storage. The caller
    must retain typed terminal handoffs, including cancellation, before propagating them.
    """
    terminal: Response | None = None
    projection = _CommentaryProjection(on_commentary)
    summary_projection = ReasoningSummaryProjection(on_reasoning_summary)
    try:
        try:
            async for event in stream:
                if event.type in ("response.completed", "response.failed", "response.incomplete"):
                    terminal = event.response
                    break  # Do not wait for EOF after an intact terminal envelope.
                projection.accept(event)
                summary_projection.accept(event)
        finally:
            await stream.close()
    except CancelledError:
        if terminal is not None:
            raise ResponseStreamCancelledError(terminal) from None
        raise
    except Exception as error:
        # The pinned HTTP stream closes in its own finally block. A close error can
        # mask a read cancellation; preserve that immediate Python exception context.
        # The SDK wraps HTTP transport errors once; unwrap only that known boundary.
        # Do not scan arbitrary chains or turn normal transport failures into cancels.
        masked = error
        if isinstance(error, APIConnectionError) and isinstance(error.__cause__, Exception):
            masked = error.__cause__
        if isinstance(masked.__context__, CancelledError):
            if terminal is not None:
                raise ResponseStreamCancelledError(terminal) from None
            raise masked.__context__ from None
        if terminal is not None:
            raise ResponseStreamCleanupError(terminal) from None
        raise
    if terminal is None:
        raise ResponseStreamProtocolError("The stream ended without a terminal response")
    return terminal

apps/api/src/caliburn/adapters/v4a_parse:
"""Parse single-body V4A updates; no paths, filesystem, or first-match locator.

The section/chunk algorithm is adapted from OpenAI Agents Python apply_diff.py
(MIT). Attribution and changes: apps/api/THIRD_PARTY_NOTICES.md; the full
license also ships beside this module as _openai_agents_license.txt.
Caliburn requires full input consumption and leaves location to its editor.
"""

import re
from dataclasses import dataclass
from typing import Literal


@dataclass(frozen=True, slots=True)
class V4AChunk:
    original_index: int
    deleted_lines: tuple[str, ...]
    inserted_lines: tuple[str, ...]


@dataclass(frozen=True, slots=True)
class V4AHunk:
    anchors: tuple[str, ...]
    context: tuple[str, ...]
    chunks: tuple[V4AChunk, ...]
    end_of_file: bool


class V4ASyntaxError(ValueError):
    """The entire body update must be rejected, including earlier valid hunks."""


def parse_body_diff(diff: str) -> tuple[V4AHunk, ...]:
    """Parse update hunks, optional terminal EOF/End Patch, and stacked anchors.

    Numeric unified headers, file envelopes, unconsumed tails, NUL and lone CR
    are not body V4A. Error messages deliberately do not echo arbitrary input.
    """
    if "\x00" in diff or "\r" in diff.replace("\r\n", ""):
        raise V4ASyntaxError("Diff contains an unsupported control character")
    lines = diff.replace("\r\n", "\n").split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    if lines and lines[-1] == "*** End Patch":
        lines.pop()
    if not lines:
        raise V4ASyntaxError("Provide a nonempty body update")

    hunks: list[V4AHunk] = []
    index = 0
    while index < len(lines):
        anchors: list[str] = []
        header_count = 0
        while index < len(lines) and (lines[index] == "@@" or lines[index].startswith("@@ ")):
            header = lines[index]
            if re.match(r"@@ [+-]\d", header):
                raise V4ASyntaxError("Use V4A @@ or source-text anchors, not numeric diff headers")
            if header != "@@":
                anchor = header[3:]
                if not anchor.strip():
                    raise V4ASyntaxError("A source-text anchor cannot be blank")
                anchors.append(anchor)
            index += 1
            header_count += 1
        if hunks and not header_count:
            raise V4ASyntaxError("Each subsequent hunk must start with @@")
        context, chunks, index, end_of_file = _read_section(lines, index)
        if not chunks or (not end_of_file and not any(line.strip() for line in context)):
            raise V4ASyntaxError("Each hunk needs an edit and source context or an explicit EOF")
        hunks.append(V4AHunk(tuple(anchors), context, chunks, end_of_file))
        if end_of_file and index != len(lines):
            raise V4ASyntaxError("End of File must terminate the body diff")
    return tuple(hunks)


def _read_section(
    lines: list[str], start_index: int
) -> tuple[tuple[str, ...], tuple[V4AChunk, ...], int, bool]:
    # OpenAI's section algorithm: context is the old side; each edit chunk has
    # a context-relative offset. Keep lines are never copied over actual text.
    context: list[str] = []
    deleted_lines: list[str] = []
    inserted_lines: list[str] = []
    chunks: list[V4AChunk] = []
    mode: Literal["keep", "add", "delete"] = "keep"
    index = start_index
    while index < len(lines):
        raw = lines[index]
        if raw == "@@" or raw.startswith("@@ ") or raw == "*** End of File":
            break
        if raw.startswith("***"):
            raise V4ASyntaxError("File operations and patch envelopes are not allowed")
        index += 1
        last_mode = mode
        line = raw if raw else " "
        prefix = line[0]
        if prefix == "+":
            mode = "add"
        elif prefix == "-":
            mode = "delete"
        elif prefix == " ":
            mode = "keep"
        else:
            raise V4ASyntaxError("Hunk lines must start with space, - or +")
        line_content = line[1:]
        if mode == "keep" and last_mode != mode and (deleted_lines or inserted_lines):
            chunks.append(
                V4AChunk(
                    len(context) - len(deleted_lines), tuple(deleted_lines), tuple(inserted_lines)
                )
            )
            deleted_lines = []
            inserted_lines = []
        if mode == "delete":
            deleted_lines.append(line_content)
            context.append(line_content)
        elif mode == "add":
            inserted_lines.append(line_content)
        else:
            context.append(line_content)
    if deleted_lines or inserted_lines:
        chunks.append(
            V4AChunk(len(context) - len(deleted_lines), tuple(deleted_lines), tuple(inserted_lines))
        )
    if index == start_index:
        raise V4ASyntaxError("Hunk has no lines")
    end_of_file = index < len(lines) and lines[index] == "*** End of File"
    return tuple(context), tuple(chunks), index + int(end_of_file), end_of_file

apps/api/src/caliburn/agent_execution/co:
"""Read-only handles to native windows; eligibility is owned by the application."""

from dataclasses import dataclass, field

from langchain_core.runnables import RunnableConfig
from langgraph.checkpoint.base import BaseCheckpointSaver, CheckpointTuple

from caliburn.adapters.response_serialization import NativeItems


@dataclass(frozen=True, slots=True)
class SavedContextWindow:
    checkpoint_id: str
    items: NativeItems = field(repr=False)


async def read_context_checkpoint(
    checkpointer: BaseCheckpointSaver[str], *, thread_id: str, checkpoint_id: str | None
) -> CheckpointTuple:
    """Read only. An explicit missing position never falls back to the latest one."""
    if not thread_id or checkpoint_id == "":
        raise ValueError("A context position needs nonempty identifiers")
    config: RunnableConfig = {"configurable": {"thread_id": thread_id, "checkpoint_ns": ""}}
    if checkpoint_id is not None:
        config["configurable"]["checkpoint_id"] = checkpoint_id
    saved = await checkpointer.aget_tuple(config)
    if saved is None:
        raise ValueError("The saved context position is unavailable")
    if checkpoint_id is not None and saved.checkpoint["id"] != checkpoint_id:
        raise ValueError("The saved context position does not match the requested checkpoint")
    return saved

apps/api/src/caliburn/agent_execution/pu:
"""Read public commentary from original native results, never from carried context."""

from collections.abc import AsyncIterator
from dataclasses import dataclass, field

from langchain_core.runnables import RunnableConfig
from langgraph.checkpoint.base import BaseCheckpointSaver
from openai.types.responses import Response, ResponseOutputMessage

from caliburn.adapters.reasoning_summaries import (
    PublicReasoningSummary,
    project_reasoning_summaries,
)
from caliburn.adapters.response_serialization import restore_response


@dataclass(frozen=True, slots=True)
class PublicCommentary:
    response_id: str
    message_id: str
    text: str = field(repr=False)


def project_commentary(response: Response) -> tuple[PublicCommentary, ...]:
    """A positive field allowlist, not serialization of provider output objects."""
    if response.status != "completed" or response.error is not None:
        return ()
    messages = []
    for item in response.output:
        if not (
            isinstance(item, ResponseOutputMessage)
            and item.role == "assistant"
            and item.phase == "commentary"
            and item.status == "completed"
        ):
            continue
        text = "\n\n".join(
            part.text if part.type == "output_text" else part.refusal for part in item.content
        )
        if text.strip():
            messages.append(PublicCommentary(response.id, item.id, text))
    return tuple(messages)


async def read_public_commentary(
    checkpointer: BaseCheckpointSaver[str], *, thread_id: str
) -> tuple[PublicCommentary, ...]:
    groups = [
        project_commentary(response) async for response in _saved_responses(checkpointer, thread_id)
    ]
    return tuple(message for group in reversed(groups) for message in group)


async def read_public_reasoning_summaries(
    checkpointer: BaseCheckpointSaver[str], *, thread_id: str
) -> tuple[PublicReasoningSummary, ...]:
    groups = [
        project_reasoning_summaries(response)
        async for response in _saved_responses(checkpointer, thread_id)
    ]
    return tuple(summary for group in reversed(groups) for summary in group)


async def _saved_responses(
    checkpointer: BaseCheckpointSaver[str], thread_id: str
) -> AsyncIterator[Response]:
    """Retained native history survives compaction; no Graph invocation or extra store.

    Native saver history is newest first. A saved model pending write is newer than
    its checkpoint's channel values. Only response originals are read, never input_items.
    """
    config: RunnableConfig = {"configurable": {"thread_id": thread_id, "checkpoint_ns": ""}}
    seen: set[str] = set()
    async for saved in checkpointer.alist(config):
        snapshots = [
            value
            for _task_id, channel, value in saved.pending_writes or ()
            if channel == "response_snapshot"
        ]
        snapshots.append(saved.checkpoint["channel_values"].get("response_snapshot"))
        for snapshot in snapshots:
            if not snapshot:
                continue
            if not isinstance(snapshot, dict):
                raise ValueError("A saved response original is unavailable")
            response_id = snapshot.get("id")
            if isinstance(response_id, str) and response_id in seen:
                continue
            response = restore_response(snapshot)
            seen.add(response.id)
            yield response

