"""Validate saved request counts; never guess, truncate or select another model."""

from dataclasses import dataclass
from typing import TypedDict
from uuid import UUID

from caliburn.adapters.openai_models import ModelCapacityLimits as ModelCapacityLimits
from caliburn.adapters.openai_responses import ResponseRequest

# Each attempt costs one more exact count, so the owner of an oversized first request
# gets a small fixed number of reductions before the work is reported as capacity-blocked.
MAX_FIRST_REQUEST_FITS = 3
# Shared complete-Step/handoff policy; not a provider capacity or rate-limit guarantee.
MID_WORK_COMPACTION_THRESHOLD_TOKENS = 160_000


class ReceivedInputCount(TypedDict):
    input_tokens: int
    attempt_id: UUID


class RequestCapacityError(ValueError):
    """Do not issue generation with this saved request and capacity policy."""


class RequestOverCapacityError(RequestCapacityError):
    """The exact saved count exceeds the hard input limit; only the data's owner may shrink it."""

    def __init__(self, *, input_tokens: int, allowed_input_tokens: int) -> None:
        self.input_tokens = input_tokens
        self.allowed_input_tokens = allowed_input_tokens
        super().__init__("The counted request exceeds the configured model capacity")


@dataclass(frozen=True, slots=True)
class RequestOverflow:
    """A counted, unsent first request above its hard input limit; attempt starts at 1."""

    input_tokens: int
    allowed_input_tokens: int
    attempt: int


class CompactionRequiredError(ValueError):
    """A complete-Step boundary needs explicit compaction before the next request."""


def validate_capacity_limits(limits: ModelCapacityLimits) -> None:
    if set(limits) != {"model", "max_input_tokens", "context_window_tokens", "max_output_tokens"}:
        raise ValueError("Configure explicit model capacity limits")
    if not isinstance(limits["model"], str) or not limits["model"].strip():
        raise ValueError("Configure a model for the capacity limits")
    for value in (
        limits["max_input_tokens"],
        limits["context_window_tokens"],
        limits["max_output_tokens"],
    ):
        if type(value) is not int or value < 1:
            raise ValueError("Configure positive integer capacity limits")


def allowed_input_tokens(request: ResponseRequest, limits: ModelCapacityLimits) -> int:
    """Highest counted input that still leaves the requested output inside the window."""
    output_tokens: int = request.create_payload()["max_output_tokens"]
    return min(limits["max_input_tokens"], limits["context_window_tokens"] - output_tokens)


def require_request_limits(request: ResponseRequest, limits: ModelCapacityLimits) -> None:
    """Reject known configuration errors before making even the remote count request."""
    validate_capacity_limits(limits)
    payload = request.create_payload()
    if payload["model"] != limits["model"]:
        raise RequestCapacityError("The request model has no matching capacity policy")
    if payload["max_output_tokens"] > min(
        limits["max_output_tokens"], limits["context_window_tokens"]
    ):
        raise RequestCapacityError("The requested output exceeds the configured capacity")


def require_request_capacity(
    request: ResponseRequest,
    count: ReceivedInputCount,
    limits: ModelCapacityLimits,
    *,
    completed_steps: int,
) -> None:
    require_request_limits(request, limits)
    tokens = count["input_tokens"]
    if type(tokens) is not int or tokens < 0 or not isinstance(count["attempt_id"], UUID):
        raise RequestCapacityError("The saved input count is invalid; capacity is unknown")
    allowed = allowed_input_tokens(request, limits)
    if tokens > allowed:
        raise RequestOverCapacityError(input_tokens=tokens, allowed_input_tokens=allowed)
    # Caliburn policy, not a provider context-window guarantee. First-request preparation
    # and actual compact/adoption belong to their own workflow, not to this count gate.
    if completed_steps > 0 and tokens >= MID_WORK_COMPACTION_THRESHOLD_TOKENS:
        raise CompactionRequiredError("The next request requires explicit boundary compaction")

"""Provider-directed delays and bounded jitter; durable admission remains the work owner."""

from dataclasses import dataclass
from datetime import datetime
from email.utils import parsedate_to_datetime
from math import isfinite

from openai import APIError, APIStatusError

from caliburn.adapters.openai_failures import ResponseFailureKind, classify_response_failure


@dataclass(frozen=True, slots=True)
class ResponseRetryPolicy:
    """Waits between sends of one logical request.

    A rate limit gets its own, longer schedule: a tokens-per-minute bucket refills over about a
    minute, and rejected tries also count against it, so retrying quickly only keeps it empty.
    """

    initial_backoff_seconds: float = 2.0
    maximum_backoff_seconds: float = 30.0
    rate_limit_initial_backoff_seconds: float = 10.0
    rate_limit_maximum_backoff_seconds: float = 60.0

    def __post_init__(self) -> None:
        for initial, maximum in (
            (self.initial_backoff_seconds, self.maximum_backoff_seconds),
            (self.rate_limit_initial_backoff_seconds, self.rate_limit_maximum_backoff_seconds),
        ):
            if not (isfinite(initial) and isfinite(maximum) and 0 < initial <= maximum):
                raise ValueError("Retry backoff must have finite positive ordered bounds")

    def delay_seconds(
        self, error: APIError, *, attempt_number: int, now: datetime, random_fraction: float
    ) -> float | None:
        """None forbids retry. A server delay is never shortened to the local backoff cap."""
        if attempt_number < 1 or not 0 <= random_fraction <= 1 or now.utcoffset() is None:
            raise ValueError("Use a positive attempt ordinal, aware clock and unit random value")
        kind = classify_response_failure(error).kind
        if kind not in (
            ResponseFailureKind.REMOTE_RESULT_UNKNOWN,
            ResponseFailureKind.TRANSIENT_SERVICE,
            ResponseFailureKind.RATE_LIMITED,
        ):
            return None
        server_delay = _server_delay(error, now)
        if server_delay is not None:
            # An excessive numeric value is not permission to fall back to a shorter wait.
            return server_delay if isfinite(server_delay) else None
        initial, maximum = (
            (self.rate_limit_initial_backoff_seconds, self.rate_limit_maximum_backoff_seconds)
            if kind is ResponseFailureKind.RATE_LIMITED
            else (self.initial_backoff_seconds, self.maximum_backoff_seconds)
        )
        backoff = min(maximum, initial * 2.0 ** min(attempt_number - 1, 1000))
        return backoff * (1 - 0.25 * random_fraction)


def _server_delay(error: APIError, now: datetime) -> float | None:
    if not isinstance(error, APIStatusError):
        return None
    headers = error.response.headers
    for name, divisor in (("retry-after-ms", 1000), ("retry-after", 1)):
        raw = headers.get(name)
        if raw is None:
            continue
        try:
            delay = float(raw) / divisor
        except ValueError:
            continue
        if delay >= 0:
            return delay
        if not isfinite(delay):
            return float("inf")
    raw = headers.get("retry-after")
    if raw is None:
        return None
    try:
        date = parsedate_to_datetime(raw)
        if date.utcoffset() is None:
            return None
        return max(0.0, (date - now).total_seconds())
    except ValueError, TypeError, OverflowError:
        return None

"""Inspect complete Responses items without equating API completion with product completion."""

from dataclasses import dataclass
from enum import StrEnum

from openai.types.responses import Response, ResponseFunctionToolCall, ResponseOutputMessage
from openai.types.responses.response_reasoning_item import ResponseReasoningItem


class ResponseAction(StrEnum):
    EXECUTE_TOOLS = "execute_tools"
    CONTINUE = "continue"
    DELIVER_ANSWER = "deliver_answer"


class IncompleteModelResponseError(ValueError):
    """The original response must be retained, but cannot yet drive tool effects."""


class UnsupportedModelResponseError(ValueError):
    """The returned operation is not supported by this application's execution contract."""


@dataclass(frozen=True, slots=True)
class ResponseStep:
    action: ResponseAction
    calls: tuple[ResponseFunctionToolCall, ...]
    messages: tuple[ResponseOutputMessage, ...]


def inspect_response_step(response: Response) -> ResponseStep:
    """Derive routing only; callers must save the original response before any effects.

    Commentary is not final. Calls take priority even if a final-phase message coexists.
    Unknown item/phase protocols stop explicitly instead of silently dropping output.
    """
    if response.status != "completed" or response.error is not None:
        raise IncompleteModelResponseError("The model response is not successfully completed")
    if response.incomplete_details is not None:
        raise IncompleteModelResponseError("The model response reports incomplete output")
    calls: list[ResponseFunctionToolCall] = []
    messages: list[ResponseOutputMessage] = []
    seen_calls: set[str] = set()
    for item in response.output:
        if isinstance(item, ResponseReasoningItem):
            if item.status not in (None, "completed"):
                raise IncompleteModelResponseError("A reasoning item is not complete")
        elif isinstance(item, ResponseFunctionToolCall):
            if item.status not in (None, "completed"):
                raise IncompleteModelResponseError("A function call is not complete")
            if not item.call_id or not item.name or item.call_id in seen_calls:
                raise UnsupportedModelResponseError(
                    "Function identities must be nonempty and unique"
                )
            if (
                item.async_
                or item.namespace is not None
                or (item.caller is not None and item.caller.type != "direct")
            ):
                raise UnsupportedModelResponseError(
                    "Only direct local function calls are supported"
                )
            seen_calls.add(item.call_id)
            calls.append(item)
        elif isinstance(item, ResponseOutputMessage):
            if item.status != "completed":
                raise IncompleteModelResponseError("An assistant message is not complete")
            if item.phase not in ("commentary", "final_answer"):
                raise UnsupportedModelResponseError(
                    "An assistant message requires an explicit phase"
                )
            messages.append(item)
        else:
            raise UnsupportedModelResponseError("The response contains an unsupported output item")
    if calls:
        action = ResponseAction.EXECUTE_TOOLS
    elif any(
        message.phase == "final_answer"
        and any(
            (part.text if part.type == "output_text" else part.refusal).strip()
            for part in message.content
        )
        for message in messages
    ):
        action = ResponseAction.DELIVER_ANSWER
    else:
        action = ResponseAction.CONTINUE
    return ResponseStep(action, tuple(calls), tuple(messages))

