"""Per-work outbound limits and immutable request bindings; no model payloads or credentials."""

from dataclasses import dataclass
from datetime import datetime
from decimal import Decimal
from enum import StrEnum
from uuid import UUID


class OutboundKind(StrEnum):
    MODEL = "model"
    COMPACTION = "compaction"
    TOKEN_COUNT = "token_count"


class BudgetLimit(StrEnum):
    DEADLINE = "deadline"
    OUTBOUND_ATTEMPTS = "outbound_attempts"
    MODEL_STEPS = "model_steps"
    COMPACTIONS = "compactions"
    REQUEST_ATTEMPTS = "request_attempts"
    COST = "cost"


class BudgetExceededError(RuntimeError):
    def __init__(self, limit: BudgetLimit) -> None:
        self.limit = limit
        super().__init__(f"Execution budget exhausted: {limit.value}")


class BudgetConflictError(RuntimeError):
    """A saved policy, request binding, cost or failure cannot be replaced."""


def validate_cost(cost_usd: Decimal, *, positive: bool = False) -> None:
    if (
        not cost_usd.is_finite()
        or cost_usd < 0
        or (positive and cost_usd == 0)
        or cost_usd >= Decimal("1000000000")
        or cost_usd != cost_usd.quantize(Decimal("0.000000001"))
    ):
        raise ValueError("Cost must be finite USD with at most nine decimal places")


@dataclass(frozen=True, slots=True)
class ExecutionBudget:
    max_model_steps: int
    max_compactions: int
    max_outbound_attempts: int
    max_attempts_per_request: int
    deadline_at: datetime
    max_cost_usd: Decimal | None
    cost_basis: str

    def __post_init__(self) -> None:
        for value in (
            self.max_model_steps,
            self.max_compactions,
            self.max_outbound_attempts,
            self.max_attempts_per_request,
        ):
            if type(value) is not int or value < 1:
                raise ValueError("Execution limits must be positive integers")
        if self.deadline_at.utcoffset() is None or not self.cost_basis.strip():
            raise ValueError("An aware deadline and explicit cost basis are required")
        if self.max_cost_usd is not None:
            validate_cost(self.max_cost_usd, positive=True)


@dataclass(frozen=True, slots=True)
class OutboundRequest:
    request_id: UUID
    kind: OutboundKind
    fingerprint: str

    def __post_init__(self) -> None:
        if len(self.fingerprint) != 64 or any(
            c not in "0123456789abcdef" for c in self.fingerprint
        ):
            raise ValueError("Use the SHA-256 of the exact outbound payload as request fingerprint")


# The provider asked us to slow down. Waiting for it is not a fault of the work, so these
# attempts do not spend the per-request attempt budget (the execution's deadline and overall
# attempt limit still end an endless wait).
RATE_LIMITED = "rate_limited"


@dataclass(frozen=True, slots=True)
class OutboundFailure:
    failure_code: str
    retry_not_before: datetime | None

    def __post_init__(self) -> None:
        if self.failure_code not in (
            "remote_result_unknown",
            "transient_service",
            RATE_LIMITED,
            "access_blocked",
            "capacity_exceeded",
            "request_rejected",
            "response_protocol",
        ):
            raise ValueError("Use a recognized outbound failure code without provider payloads")
        if self.retry_not_before is not None:
            if self.failure_code not in (
                "remote_result_unknown",
                "transient_service",
                RATE_LIMITED,
            ):
                raise ValueError("Only retryable outbound failures can carry a retry deadline")
            if self.retry_not_before.utcoffset() is None:
                raise ValueError("An outbound retry deadline must be timezone-aware")


@dataclass(frozen=True, slots=True)
class OutboundAttempt:
    attempt_id: UUID
    request: OutboundRequest
    writer_id: UUID
    reserved_cost_usd: Decimal
    reported_cost_usd: Decimal | None
    failure: OutboundFailure | None = None


@dataclass(frozen=True, slots=True)
class OutboundAdmission:
    attempt: OutboundAttempt
    created: bool


@dataclass(frozen=True, slots=True)
class BudgetUsage:
    outbound_attempts: int
    model_steps: int
    compactions: int
    accounted_cost_usd: Decimal

"""Execution-owned budget storage; callers lock the execution before changing accounting."""

from datetime import datetime
from decimal import Decimal
from uuid import UUID

from sqlalchemy import (
    CheckConstraint,
    DateTime,
    ForeignKey,
    Index,
    Numeric,
    Text,
    case,
    func,
    select,
)
from sqlalchemy.ext.asyncio import AsyncSession
from sqlalchemy.orm import Mapped, mapped_column

from caliburn.adapters.database import Base
from caliburn.features.executions.budget_models import BudgetUsage, OutboundKind


class ExecutionBudgetRecord(Base):
    __tablename__ = "execution_budgets"
    __table_args__ = (
        CheckConstraint(
            "max_model_steps > 0 AND max_compactions > 0 AND max_outbound_attempts > 0 "
            "AND max_attempts_per_request > 0",
            name="positive_limits",
        ),
        CheckConstraint("max_cost_usd > 0 AND max_cost_usd < 1000000000", name="positive_cost"),
        CheckConstraint("btrim(cost_basis) <> ''", name="cost_basis"),
    )

    execution_id: Mapped[UUID] = mapped_column(
        ForeignKey("executions.execution_id"), primary_key=True
    )
    max_model_steps: Mapped[int] = mapped_column()
    max_compactions: Mapped[int] = mapped_column()
    max_outbound_attempts: Mapped[int] = mapped_column()
    max_attempts_per_request: Mapped[int] = mapped_column()
    deadline_at: Mapped[datetime] = mapped_column(DateTime(timezone=True))
    max_cost_usd: Mapped[Decimal | None] = mapped_column(Numeric(18, 9))
    cost_basis: Mapped[str] = mapped_column(Text)


class OutboundAttemptRecord(Base):
    __tablename__ = "execution_outbound_attempts"
    __table_args__ = (
        CheckConstraint("kind IN ('model', 'compaction', 'token_count')", name="kind"),
        CheckConstraint("fingerprint ~ '^[0-9a-f]{64}$'", name="fingerprint"),
        CheckConstraint(
            "reserved_cost_usd > 0 AND reserved_cost_usd < 1000000000", name="reserved_cost"
        ),
        CheckConstraint(
            "reported_cost_usd IS NULL OR "
            "(reported_cost_usd >= 0 AND reported_cost_usd < 1000000000)",
            name="reported_cost",
        ),
        CheckConstraint(
            "failure_code IS NULL OR failure_code IN ('remote_result_unknown', "
            "'transient_service', 'rate_limited', 'access_blocked', 'capacity_exceeded', "
            "'request_rejected', 'response_protocol')",
            name="failure_code",
        ),
        CheckConstraint(
            "retry_not_before IS NULL OR (failure_code IS NOT NULL AND "
            "failure_code IN ('remote_result_unknown', 'transient_service', 'rate_limited'))",
            name="failure_retry",
        ),
        Index("ix_execution_outbound_attempts_request", "execution_id", "request_id"),
    )

    execution_id: Mapped[UUID] = mapped_column(
        ForeignKey("execution_budgets.execution_id"), primary_key=True
    )
    attempt_id: Mapped[UUID] = mapped_column(primary_key=True)
    request_id: Mapped[UUID] = mapped_column()
    kind: Mapped[str] = mapped_column(Text)
    fingerprint: Mapped[str] = mapped_column(Text)
    writer_id: Mapped[UUID] = mapped_column()
    reserved_cost_usd: Mapped[Decimal] = mapped_column(Numeric(18, 9))
    reported_cost_usd: Mapped[Decimal | None] = mapped_column(Numeric(18, 9))
    failure_code: Mapped[str | None] = mapped_column(Text)
    retry_not_before: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    admitted_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.clock_timestamp()
    )


async def read_budget(session: AsyncSession, execution_id: UUID) -> ExecutionBudgetRecord | None:
    return await session.get(ExecutionBudgetRecord, execution_id, populate_existing=True)


async def read_attempt(
    session: AsyncSession, execution_id: UUID, attempt_id: UUID
) -> OutboundAttemptRecord | None:
    return await session.get(
        OutboundAttemptRecord, (execution_id, attempt_id), populate_existing=True
    )


async def read_request_attempts(
    session: AsyncSession, execution_id: UUID, request_id: UUID
) -> list[OutboundAttemptRecord]:
    return list(
        await session.scalars(
            select(OutboundAttemptRecord).where(
                OutboundAttemptRecord.execution_id == execution_id,
                OutboundAttemptRecord.request_id == request_id,
            )
        )
    )


async def read_usage(session: AsyncSession, execution_id: UUID) -> BudgetUsage:
    row = (
        await session.execute(
            select(
                func.count(),
                func.count(
                    func.distinct(
                        case(
                            (
                                OutboundAttemptRecord.kind == OutboundKind.MODEL.value,
                                OutboundAttemptRecord.request_id,
                            )
                        )
                    )
                ),
                func.count(
                    func.distinct(
                        case(
                            (
                                OutboundAttemptRecord.kind == OutboundKind.COMPACTION.value,
                                OutboundAttemptRecord.request_id,
                            )
                        )
                    )
                ),
                func.coalesce(
                    func.sum(
                        func.coalesce(
                            OutboundAttemptRecord.reported_cost_usd,
                            OutboundAttemptRecord.reserved_cost_usd,
                        )
                    ),
                    Decimal(0),
                ),
            ).where(OutboundAttemptRecord.execution_id == execution_id)
        )
    ).one()
    return BudgetUsage(row[0], row[1], row[2], row[3])


async def current_time(session: AsyncSession) -> datetime:
    return (await session.execute(select(func.clock_timestamp()))).scalar_one()

"""Adopt context references under the existing execution owner in the caller transaction."""

from collections.abc import Mapping
from uuid import UUID

from sqlalchemy.ext.asyncio import AsyncSession

from caliburn.features.executions import history_persistence as storage
from caliburn.features.executions import persistence, service
from caliburn.features.executions.history_models import (
    AgentRole,
    ContextBinding,
    ContextPosition,
    HistoryConflictError,
    HistoryWindowKind,
    context_thread_id,
)
from caliburn.features.executions.models import (
    ExecutionKind,
    ExecutionNotFoundError,
    ExecutionScope,
    ExecutionStatus,
    ExecutionWriter,
)


async def bind_context_history(
    session: AsyncSession, writer: ExecutionWriter, role: AgentRole
) -> ContextBinding:
    """Pin the role's adopted base once, including an explicitly empty base."""
    await service.lock_active_writer(session, writer)
    _require_role(writer.scope, role)
    record = await storage.read_binding(session, writer.scope, role)
    if record is None:
        head = await storage.lock_head(session, writer.scope.job_file_id, role)
        record = storage.ContextHistoryBindingRecord(
            job_file_id=writer.scope.job_file_id,
            execution_id=writer.scope.execution_id,
            role=role.value,
            base_thread_id=head.thread_id,
            base_checkpoint_id=head.checkpoint_id,
            base_kind=head.kind,
        )
        session.add(record)
        await session.flush()
    return _binding(record)


async def read_context_history(
    session: AsyncSession, scope: ExecutionScope, role: AgentRole
) -> ContextBinding | None:
    """Read a fixed binding without creating rows or refreshing its base."""
    await service.read_execution(session, scope)
    _require_role(scope, role)
    record = await storage.read_binding(session, scope, role)
    return _binding(record) if record is not None else None


async def read_adopted_context(
    session: AsyncSession, job_file_id: UUID, role: AgentRole
) -> ContextPosition | None:
    """Return only the adopted reference, never an arbitrary latest saver checkpoint."""
    if not isinstance(role, AgentRole):
        raise HistoryConflictError("Expected an agent role")
    record = await storage.read_head(session, job_file_id, role)
    return _head_position(record) if record is not None else None


async def request_context_compaction(
    session: AsyncSession, writer: ExecutionWriter, role: AgentRole
) -> None:
    """Idempotent intent only; completion eligibility decides whether it can be consumed."""
    await service.lock_active_writer(session, writer)
    _require_role(writer.scope, role)
    record = await storage.read_binding(session, writer.scope, role)
    if record is None or record.prepared_thread_id is None:
        raise HistoryConflictError("Prepare this role's context before requesting compaction")
    record.compact_requested = True
    await session.flush()


async def read_completed_compaction_request(
    session: AsyncSession, job_file_id: UUID, role: AgentRole, position: ContextPosition
) -> bool:
    """Only the selected completed work can request the next preparation.

    An adopted prepared position already consumed the request, including after a
    cancelled Turn. Never walk past it to resurrect the preceding completed intent.
    """
    if position.kind != HistoryWindowKind.COMPLETED_WORK:
        return False
    origin = await storage.read_position_origin(session, job_file_id, role, position)
    if origin is None:
        raise HistoryConflictError("The selected completed context is unavailable")
    scope = ExecutionScope(
        job_file_id,
        origin.execution_id,
        ExecutionKind.CONSULTANT_TURN
        if role == AgentRole.JOB_CONSULTANT
        else ExecutionKind.MEMORY_BATCH,
    )
    if (await service.read_execution(session, scope)).status != ExecutionStatus.COMPLETED:
        raise HistoryConflictError("A context request requires completed execution")
    return origin.compact_requested


async def read_previous_completed_execution(
    session: AsyncSession, scope: ExecutionScope, role: AgentRole
) -> ExecutionScope | None:
    """Follow this execution's fixed history ancestry through prepared-only windows.

    Reads no native context bodies and does not advance history. An unavailable
    reference is an error, never permission to substitute an empty initial baseline.
    """
    binding = await read_context_history(session, scope, role)
    if binding is None:
        raise HistoryConflictError("The current execution has no fixed context binding")
    position = binding.base
    visited: set[ContextPosition] = set()
    while position is not None:
        if position in visited:
            raise HistoryConflictError("The context ancestry contains a cycle")
        visited.add(position)
        origin = await storage.read_position_origin(session, scope.job_file_id, role, position)
        if origin is None:
            raise HistoryConflictError("A fixed context ancestor is unavailable")
        previous = ExecutionScope(scope.job_file_id, origin.execution_id, scope.kind)
        if position.kind == HistoryWindowKind.COMPLETED_WORK:
            if (
                await service.read_execution(session, previous)
            ).status != ExecutionStatus.COMPLETED:
                raise HistoryConflictError(
                    "A completed history reference lacks completed execution"
                )
            return previous
        position = _binding(origin).base
    return None


async def adopt_prepared_context(
    session: AsyncSession, writer: ExecutionWriter, role: AgentRole, position: ContextPosition
) -> ContextBinding:
    """Adopt an own pre-work window, or reuse the exact prepared base after cancellation.

    A reused prepared base may belong to an earlier execution; a different foreign reference
    is never eligible. The caller must verify the referenced native checkpoint is durable.
    """
    await service.lock_active_writer(session, writer)
    _require_role(writer.scope, role)
    record = await storage.read_binding(session, writer.scope, role)
    if record is None:
        raise HistoryConflictError("Bind the context history before adopting preparation")
    binding = _binding(record)
    if position.kind != HistoryWindowKind.PREPARED_HISTORY or (
        position != binding.base
        and position.thread_id
        != context_thread_id(writer.scope, role, HistoryWindowKind.PREPARED_HISTORY)
    ):
        raise HistoryConflictError("The prepared window does not belong to this role and execution")
    if binding.prepared is not None:
        if binding.prepared != position:
            raise HistoryConflictError("The prepared context has already been fixed")
        return binding
    head = await storage.lock_head(session, writer.scope.job_file_id, role)
    if _head_position(head) != binding.base:
        raise HistoryConflictError("The adopted context no longer matches the pinned base")
    head.thread_id = position.thread_id
    head.checkpoint_id = position.checkpoint_id
    head.kind = position.kind.value
    record.prepared_thread_id = position.thread_id
    record.prepared_checkpoint_id = position.checkpoint_id
    await session.flush()
    return _binding(record)


async def complete_context_histories(
    session: AsyncSession, writer: ExecutionWriter, positions: Mapping[AgentRole, ContextPosition]
) -> None:
    """Atomically adopt all role references and finish eligibility in the caller's transaction.

    The caller coordinates JD/interview/Memory effects in this SAME transaction. Native
    checkpoint existence and product completion are workflow responsibilities, not Graph END.
    """
    execution = await persistence.read_execution(session, writer.scope, lock=True)
    if execution is None:
        raise ExecutionNotFoundError("Execution not found in the requested scope")
    replay = execution.status == ExecutionStatus.COMPLETED
    if replay:
        # The existing owner still fences the writer on an ACK-loss replay.
        await service.finish_execution(session, writer, ExecutionStatus.COMPLETED)
    else:
        await service.lock_active_writer(session, writer)

    roles = _required_roles(writer.scope.kind)
    if set(positions) != set(roles) or any(not isinstance(role, AgentRole) for role in positions):
        raise HistoryConflictError("Completion requires exactly the execution's roles")
    records: dict[AgentRole, storage.ContextHistoryBindingRecord] = {}
    for role in roles:
        position = positions[role]
        if position.kind != HistoryWindowKind.COMPLETED_WORK or not _belongs_to_completed_role(
            writer.scope, role, position.thread_id
        ):
            raise HistoryConflictError(
                "The completed window does not belong to this execution role"
            )
        record = await storage.read_binding(session, writer.scope, role)
        if record is None or record.prepared_thread_id is None:
            raise HistoryConflictError(
                "Every role must have an adopted preparation before completion"
            )
        if replay and _binding(record).completed != position:
            raise HistoryConflictError("Completion replay must use the original context references")
        records[role] = record
    if replay:
        # A later execution may already have advanced the head; never touch it during replay.
        return

    heads: dict[AgentRole, storage.ContextHistoryHeadRecord] = {}
    for role in sorted(roles):
        head = await storage.lock_head(session, writer.scope.job_file_id, role)
        if _head_position(head) != _binding(records[role]).prepared:
            raise HistoryConflictError("The adopted head no longer matches this work's preparation")
        heads[role] = head
    # Check all references before changing anything. The owner rejects pause intent here,
    # under the same execution lock used by pause/cancel and writer replacement.
    await service.finish_execution(session, writer, ExecutionStatus.COMPLETED)
    for role in roles:
        position = positions[role]
        heads[role].thread_id = position.thread_id
        heads[role].checkpoint_id = position.checkpoint_id
        heads[role].kind = position.kind.value
        records[role].completed_thread_id = position.thread_id
        records[role].completed_checkpoint_id = position.checkpoint_id
    await session.flush()


def _belongs_to_completed_role(scope: ExecutionScope, role: AgentRole, thread_id: str) -> bool:
    """A uses its root; Memory may adopt a role's exact native stage window.

    The Memory parent separately proves that this is the completed current candidate
    stage. This owner checks execution/role ownership, not candidate business semantics.
    """
    root = context_thread_id(scope, role, HistoryWindowKind.COMPLETED_WORK)
    if thread_id == root:
        return True
    prefix = f"{root}:stage:"
    if scope.kind != ExecutionKind.MEMORY_BATCH or not thread_id.startswith(prefix):
        return False
    parts = thread_id.removeprefix(prefix).split(":")
    if len(parts) != 2:
        return False
    try:
        return all(str(UUID(value)) == value for value in parts)
    except ValueError:
        return False


def _required_roles(kind: ExecutionKind) -> tuple[AgentRole, ...]:
    if kind == ExecutionKind.CONSULTANT_TURN:
        return (AgentRole.JOB_CONSULTANT,)
    return (AgentRole.WORK_SITUATION_ANALYST, AgentRole.WORK_UNDERSTANDING_ANALYST)


def _require_role(scope: ExecutionScope, role: AgentRole) -> None:
    if not isinstance(role, AgentRole) or role not in _required_roles(scope.kind):
        raise HistoryConflictError("This role does not belong to the execution kind")


def _position(
    thread_id: str | None, checkpoint_id: str | None, kind: str | None
) -> ContextPosition | None:
    if thread_id is None:
        return None
    if checkpoint_id is None or kind is None:
        raise HistoryConflictError("The persisted context position is incomplete")
    return ContextPosition(thread_id, checkpoint_id, HistoryWindowKind(kind))


def _head_position(record: storage.ContextHistoryHeadRecord) -> ContextPosition | None:
    return _position(record.thread_id, record.checkpoint_id, record.kind)


def _binding(record: storage.ContextHistoryBindingRecord) -> ContextBinding:
    return ContextBinding(
        AgentRole(record.role),
        _position(record.base_thread_id, record.base_checkpoint_id, record.base_kind),
        _position(
            record.prepared_thread_id,
            record.prepared_checkpoint_id,
            HistoryWindowKind.PREPARED_HISTORY,
        ),
        _position(
            record.completed_thread_id,
            record.completed_checkpoint_id,
            HistoryWindowKind.COMPLETED_WORK,
        ),
    )

