"""Pure, bounded updates: changing a shared definition never copies it into tasks."""

from dataclasses import replace
from uuid import UUID, uuid4

from caliburn.features.job_description.capabilities import (
    Capability,
    CapabilityChange,
    CapabilityField,
    CapabilityInUseError,
    CapabilityTargetNotFoundError,
    CreateCapability,
    DeleteCapability,
    InvalidCapabilityChangeError,
    ReorderCapability,
    ReorderTaskCapability,
    ReviseCapability,
    SetTaskCapability,
    TaskCapabilityLink,
)


def _ordered_ids(ids: tuple[UUID, ...], target: UUID, before: UUID | None) -> tuple[UUID, ...]:
    if target not in ids or (before is not None and before not in ids):
        raise CapabilityTargetNotFoundError("Ordering target must belong to the same group")
    if target == before:
        return ids
    remaining = tuple(identity for identity in ids if identity != target)
    index = len(remaining) if before is None else remaining.index(before)
    return (*remaining[:index], target, *remaining[index:])


def apply_capability_change(
    capabilities: tuple[Capability, ...],
    links: tuple[TaskCapabilityLink, ...],
    task_ids: tuple[UUID, ...],
    change: CapabilityChange,
) -> tuple[tuple[Capability, ...], tuple[TaskCapabilityLink, ...], Capability | None]:
    if isinstance(change, CreateCapability):
        created = Capability(uuid4(), uuid4(), change.kind, change.name, change.description)
        return (*capabilities, created), links, created
    by_id = {item.capability_id: item for item in capabilities}
    target = by_id.get(change.capability_id)
    if target is None:
        raise CapabilityTargetNotFoundError("Capability is not selected in this JD")
    if isinstance(change, ReviseCapability):
        name, description = target.name, target.description
        for item in change.changes:
            if item.field is CapabilityField.NAME:
                name = item.value
            else:
                description = item.value
        updated = replace(target, name=name, description=description)
        if updated == target:
            return capabilities, links, None
        updated = replace(updated, content_revision_id=uuid4())
        return tuple(updated if item == target else item for item in capabilities), links, updated
    if isinstance(change, DeleteCapability):
        if any(link.capability_id == target.capability_id for link in links):
            raise CapabilityInUseError("Capability is still linked to a task")
        return tuple(item for item in capabilities if item != target), links, None
    if isinstance(change, ReorderCapability):
        group = tuple(item.capability_id for item in capabilities if item.kind == target.kind)
        ordered = iter(_ordered_ids(group, target.capability_id, change.before_capability_id))
        return (
            tuple(
                by_id[next(ordered)] if item.kind == target.kind else item for item in capabilities
            ),
            links,
            None,
        )
    if change.task_id not in task_ids:
        raise CapabilityTargetNotFoundError("Task is not selected in this JD")
    link = TaskCapabilityLink(change.task_id, target.capability_id)
    if isinstance(change, SetTaskCapability):
        if type(change.linked) is not bool:
            raise InvalidCapabilityChangeError("Choose whether this task uses the capability")
        if change.linked:
            updated_links = links if link in links else (*links, link)
        else:
            updated_links = tuple(item for item in links if item != link)
    elif isinstance(change, ReorderTaskCapability):
        group = tuple(
            item.capability_id
            for item in links
            if item.task_id == change.task_id and by_id[item.capability_id].kind == target.kind
        )
        ordered = iter(_ordered_ids(group, target.capability_id, change.before_capability_id))
        updated_links = tuple(
            TaskCapabilityLink(item.task_id, next(ordered))
            if item.task_id == change.task_id and by_id[item.capability_id].kind == target.kind
            else item
            for item in links
        )
    else:
        raise TypeError("Unsupported capability change")
    # Cross-task ordering has no semantics; keep a stable representation for no-op comparison.
    return capabilities, tuple(sorted(updated_links, key=lambda item: item.task_id)), None


def capability_change_payload(change: CapabilityChange) -> list[dict[str, str | bool | None]]:
    match change:
        case CreateCapability():
            return [
                {
                    "action": "create_capability",
                    "kind": change.kind.value,
                    "name": change.name,
                    "description": change.description,
                }
            ]
        case ReviseCapability():
            payload: list[dict[str, str | bool | None]] = [
                {"action": "revise_capability", "capability_id": str(change.capability_id)}
            ]
            for item in change.changes:
                payload.append({"field": item.field.value, "value": item.value})
            return payload
        case DeleteCapability():
            return [{"action": "delete_capability", "capability_id": str(change.capability_id)}]
        case ReorderCapability():
            return [
                {
                    "action": "reorder_capability",
                    "capability_id": str(change.capability_id),
                    "before_capability_id": str(change.before_capability_id)
                    if change.before_capability_id
                    else None,
                }
            ]
        case SetTaskCapability():
            return [
                {
                    "action": "set_task_capability",
                    "task_id": str(change.task_id),
                    "capability_id": str(change.capability_id),
                    "linked": change.linked,
                }
            ]
        case ReorderTaskCapability():
            return [
                {
                    "action": "reorder_task_capability",
                    "task_id": str(change.task_id),
                    "capability_id": str(change.capability_id),
                    "before_capability_id": str(change.before_capability_id)
                    if change.before_capability_id
                    else None,
                }
            ]

"""Read the original JD ledger and fixed values; execution qualification stays with its owner."""

from dataclasses import dataclass
from uuid import UUID

from sqlalchemy.ext.asyncio import AsyncSession

from caliburn.features.job_description import candidate_persistence, persistence, source_persistence
from caliburn.features.job_description.models import JdProfile, ProfileField
from caliburn.features.job_description.sources import JdSourceReference
from caliburn.features.job_description.work_queries import JdWorkRevision, read_work_at


class JdChangeHistoryUnavailableError(LookupError):
    """A required historical endpoint or original operation cannot be recovered."""


@dataclass(frozen=True, slots=True)
class JdChangeSnapshot:
    profile: JdProfile
    work: JdWorkRevision
    sources: tuple[JdSourceReference, ...]


@dataclass(frozen=True, slots=True)
class ManualJdOperation:
    before_revision_id: UUID
    after_revision_id: UUID
    kind: str
    item_ids: frozenset[UUID]
    profile_fields: frozenset[ProfileField]


@dataclass(frozen=True, slots=True)
class ManualJdRange:
    base_revision_id: UUID
    start_revision_id: UUID
    initial_base: bool
    operations: tuple[ManualJdOperation, ...]


async def read_manual_change_range(
    session: AsyncSession,
    job_file_id: UUID,
    execution_id: UUID,
    *,
    start_revision_id: UUID,
    previous_completed_execution_id: UUID | None,
) -> ManualJdRange:
    """Caller supplies the completed execution selected by public history ownership."""
    current = await candidate_persistence.read_candidate(session, job_file_id, execution_id)
    if current is None or current.status != "open" or current.base_revision_id != start_revision_id:
        raise JdChangeHistoryUnavailableError(
            "The current candidate does not match the fixed start"
        )
    since = None
    if previous_completed_execution_id is None:
        base = (await persistence.read_document(session, job_file_id)).initial_revision_id
    else:
        previous = await candidate_persistence.read_candidate(
            session, job_file_id, previous_completed_execution_id
        )
        if previous is None or previous.status != "adopted":
            raise JdChangeHistoryUnavailableError("The completed Turn has no adopted JD position")
        base, since = previous.current_revision_id, previous.created_at
    chain = dict(
        await persistence.read_revision_interval(
            session,
            job_file_id,
            base_revision_id=base,
            end_revision_id=start_revision_id,
        )
    )
    if base not in chain:
        raise JdChangeHistoryUnavailableError("The fixed JD base is not a retained ancestor")
    ordered = [start_revision_id]
    while ordered[-1] != base:
        parent = chain.get(ordered[-1])
        if parent is None or parent in ordered:
            raise JdChangeHistoryUnavailableError("The JD ancestry is incomplete")
        ordered.append(parent)
    ordered.reverse()
    indexes = {revision_id: index for index, revision_id in enumerate(ordered)}
    records = await persistence.read_manual_operations(
        session,
        job_file_id,
        tuple(ordered),
        created_before=current.created_at,
        created_since=since,
    )
    effects = {
        record.result_revision_id: record.expected_revision_id
        for record in records
        if record.expected_revision_id != record.result_revision_id
    }
    if any(effects.get(revision_id) != chain[revision_id] for revision_id in ordered[1:]):
        raise JdChangeHistoryUnavailableError(
            "A formal revision lacks its original manual operation"
        )
    records = tuple(
        sorted(
            records,
            key=lambda record: (
                indexes[record.expected_revision_id],
                record.expected_revision_id != record.result_revision_id,
                record.created_at,
                record.command_id,
            ),
        )
    )
    return ManualJdRange(
        base,
        start_revision_id,
        previous_completed_execution_id is None,
        tuple(_operation(record) for record in records),
    )


async def read_change_snapshot(
    session: AsyncSession, job_file_id: UUID, revision_id: UUID
) -> JdChangeSnapshot:
    profile = await persistence.read_revision(session, job_file_id, revision_id)
    return JdChangeSnapshot(
        profile.profile,
        await read_work_at(session, job_file_id, revision_id),
        await source_persistence.read_source_references(session, job_file_id, revision_id),
    )


async def read_adopted_turn_changes(
    session: AsyncSession, job_file_id: UUID, execution_id: UUID
) -> tuple[JdChangeSnapshot, JdChangeSnapshot]:
    """Read retained before/after values; caller qualifies this as a completed Turn."""
    candidate = await candidate_persistence.read_candidate(session, job_file_id, execution_id)
    if candidate is None or candidate.status != "adopted":
        raise JdChangeHistoryUnavailableError("The Turn has no retained adopted JD endpoints")
    return (
        await read_change_snapshot(session, job_file_id, candidate.base_revision_id),
        await read_change_snapshot(session, job_file_id, candidate.current_revision_id),
    )


def _operation(record: persistence.JdOperationRecord) -> ManualJdOperation:
    """Project target hints only; original bodies stay in the immutable revision owner."""
    item_ids: set[UUID] = set()
    fields: set[ProfileField] = set()
    identity_keys = {
        "area_id",
        "task_id",
        "detail_id",
        "capability_id",
        "collaborator_id",
        "condition_id",
        "item_id",
    }

    def visit(value: object) -> None:
        if isinstance(value, list):
            for child in value:
                visit(child)
        elif isinstance(value, dict):
            for key, child in value.items():
                if key in identity_keys and child is not None:
                    if not isinstance(child, str):
                        raise JdChangeHistoryUnavailableError("Invalid original JD target identity")
                    try:
                        item_ids.add(UUID(child))
                    except ValueError as error:
                        raise JdChangeHistoryUnavailableError(
                            "Invalid original JD target identity"
                        ) from error
                elif key == "field" and (
                    record.kind == "revise_profile" or value.get("kind") == "profile_field"
                ):
                    try:
                        fields.add(ProfileField(child))
                    except (ValueError, TypeError) as error:
                        raise JdChangeHistoryUnavailableError(
                            "Invalid original profile field"
                        ) from error
                elif isinstance(child, (dict, list)):
                    visit(child)

    if not isinstance(record.request_payload, (dict, list)):
        raise JdChangeHistoryUnavailableError("Invalid original JD operation payload")
    visit(record.request_payload)
    return ManualJdOperation(
        record.expected_revision_id,
        record.result_revision_id,
        record.kind,
        frozenset(item_ids),
        frozenset(fields),
    )

"""Collaborator values and bounded edit intentions, independent of HTTP/SQL."""

from dataclasses import dataclass
from enum import StrEnum
from uuid import UUID


class InvalidCollaboratorChangeError(ValueError):
    """A collaborator edit would be ambiguous or leave an empty collaborator."""


class CollaboratorNotFoundError(ValueError):
    """A collaborator or ordering neighbour is absent from this JD revision."""


class CollaboratorField(StrEnum):
    NAME = "name"
    SCOPE_TEXT = "scope_text"


def validate_collaborator_text(name: str | None, scope_text: str | None) -> None:
    if name is None and scope_text is None:
        raise InvalidCollaboratorChangeError("A collaborator needs a name or meaningful scope text")
    for value in (name, scope_text):
        if value is not None and (not value.strip() or "\x00" in value):
            raise InvalidCollaboratorChangeError("Collaborator text must be nonblank without NUL")


@dataclass(frozen=True, slots=True)
class Collaborator:
    collaborator_id: UUID
    content_revision_id: UUID
    name: str | None
    scope_text: str | None

    def __post_init__(self) -> None:
        validate_collaborator_text(self.name, self.scope_text)


@dataclass(frozen=True, slots=True)
class JdCollaboratorsRevision:
    revision_id: UUID
    collaborators: tuple[Collaborator, ...]


@dataclass(frozen=True, slots=True)
class CreateCollaborator:
    name: str | None
    scope_text: str | None

    def __post_init__(self) -> None:
        validate_collaborator_text(self.name, self.scope_text)


@dataclass(frozen=True, slots=True)
class CollaboratorFieldChange:
    field: CollaboratorField
    value: str | None


@dataclass(frozen=True, slots=True)
class ReviseCollaborator:
    collaborator_id: UUID
    changes: tuple[CollaboratorFieldChange, ...]

    def __post_init__(self) -> None:
        fields = [change.field for change in self.changes]
        if not fields or len(fields) != len(set(fields)):
            raise InvalidCollaboratorChangeError(
                "Choose at least one field, and change each field once"
            )


@dataclass(frozen=True, slots=True)
class DeleteCollaborator:
    collaborator_id: UUID


@dataclass(frozen=True, slots=True)
class ReorderCollaborator:
    collaborator_id: UUID
    before_collaborator_id: UUID | None


type CollaboratorChange = (
    CreateCollaborator | ReviseCollaborator | DeleteCollaborator | ReorderCollaborator
)


@dataclass(frozen=True, slots=True)
class EditJdCollaborators:
    command_id: UUID
    expected_revision_id: UUID
    change: CollaboratorChange


def collaborator_change_payload(change: CollaboratorChange) -> list[dict[str, str | None]]:
    """Stable original intent; not a second editable collaborator collection."""
    match change:
        case CreateCollaborator():
            return [
                {
                    "action": "create_collaborator",
                    "name": change.name,
                    "scope_text": change.scope_text,
                }
            ]
        case ReviseCollaborator():
            return [
                {"action": "revise_collaborator", "collaborator_id": str(change.collaborator_id)},
                *[{"field": item.field.value, "value": item.value} for item in change.changes],
            ]
        case DeleteCollaborator():
            return [
                {"action": "delete_collaborator", "collaborator_id": str(change.collaborator_id)}
            ]
        case ReorderCollaborator():
            return [
                {
                    "action": "reorder_collaborator",
                    "collaborator_id": str(change.collaborator_id),
                    "before_collaborator_id": str(change.before_collaborator_id)
                    if change.before_collaborator_id
                    else None,
                }
            ]

"""Pure changes preserve condition identity and order independently within each kind."""

from dataclasses import replace
from uuid import uuid4

from caliburn.features.job_description.conditions import (
    ConditionChange,
    ConditionKindChange,
    ConditionNotFoundError,
    ConditionTextChange,
    CreateCondition,
    DeleteCondition,
    JobCondition,
    ReorderCondition,
    ReviseCondition,
)


def apply_condition_change(
    conditions: tuple[JobCondition, ...],
    change: ConditionChange,
) -> tuple[tuple[JobCondition, ...], JobCondition | None]:
    if isinstance(change, CreateCondition):
        created = JobCondition(uuid4(), uuid4(), change.kind, change.text)
        return (*conditions, created), created
    target = next((item for item in conditions if item.condition_id == change.condition_id), None)
    if target is None:
        raise ConditionNotFoundError("Condition is not in the selected JD")
    if isinstance(change, ReviseCondition):
        kind, text = target.kind, target.text
        for item in change.changes:
            match item:
                case ConditionTextChange():
                    text = item.text
                case ConditionKindChange():
                    kind = item.kind
        revised = replace(target, kind=kind, text=text)
        if revised == target:
            return conditions, None
        revised = replace(revised, content_revision_id=uuid4())
        if kind != target.kind:
            # Reclassification retains identity and appends to the destination kind.
            return (*[item for item in conditions if item != target], revised), revised
        return tuple(revised if item == target else item for item in conditions), revised
    if isinstance(change, DeleteCondition):
        return tuple(item for item in conditions if item != target), None
    if isinstance(change, ReorderCondition):
        if change.before_condition_id == target.condition_id:
            return conditions, None
        group = [item for item in conditions if item.kind == target.kind and item != target]
        if change.before_condition_id is None:
            group.append(target)
        else:
            index = next(
                (
                    index
                    for index, item in enumerate(group)
                    if item.condition_id == change.before_condition_id
                ),
                None,
            )
            if index is None:
                raise ConditionNotFoundError("Ordering neighbour is not in this condition kind")
            group.insert(index, target)
        reordered = iter(group)
        return tuple(
            next(reordered) if item.kind == target.kind else item for item in conditions
        ), None
    raise TypeError("Unsupported condition change")

"""Job-wide conditions are classified statements, never implicit task requirements."""

from dataclasses import dataclass
from enum import StrEnum
from uuid import UUID


class InvalidConditionChangeError(ValueError):
    """A condition must have meaningful text and unambiguous changes."""


class ConditionNotFoundError(ValueError):
    """A condition or ordering neighbour is absent from the selected group."""


class ConditionKind(StrEnum):
    WORK_ENVIRONMENT = "work_environment"
    SCHEDULE_TRAVEL = "schedule_travel"
    SHARED_AUTHORITY = "shared_authority"
    SHARED_COLLABORATION = "shared_collaboration"
    QUALIFICATION = "qualification"


def validate_condition_text(text: str) -> None:
    if not text.strip() or "\x00" in text:
        raise InvalidConditionChangeError("Condition text must be nonblank without NUL")


@dataclass(frozen=True, slots=True)
class JobCondition:
    condition_id: UUID
    content_revision_id: UUID
    kind: ConditionKind
    text: str

    def __post_init__(self) -> None:
        validate_condition_text(self.text)


@dataclass(frozen=True, slots=True)
class JdConditionsRevision:
    revision_id: UUID
    conditions: tuple[JobCondition, ...]


@dataclass(frozen=True, slots=True)
class CreateCondition:
    kind: ConditionKind
    text: str

    def __post_init__(self) -> None:
        validate_condition_text(self.text)


@dataclass(frozen=True, slots=True)
class ConditionTextChange:
    text: str

    def __post_init__(self) -> None:
        validate_condition_text(self.text)


@dataclass(frozen=True, slots=True)
class ConditionKindChange:
    kind: ConditionKind


type ConditionFieldChange = ConditionTextChange | ConditionKindChange


@dataclass(frozen=True, slots=True)
class ReviseCondition:
    condition_id: UUID
    changes: tuple[ConditionFieldChange, ...]

    def __post_init__(self) -> None:
        fields = [type(change) for change in self.changes]
        if not fields or len(fields) != len(set(fields)):
            raise InvalidConditionChangeError("Choose at least one field, and change each once")


@dataclass(frozen=True, slots=True)
class DeleteCondition:
    condition_id: UUID


@dataclass(frozen=True, slots=True)
class ReorderCondition:
    condition_id: UUID
    before_condition_id: UUID | None


type ConditionChange = CreateCondition | ReviseCondition | DeleteCondition | ReorderCondition


@dataclass(frozen=True, slots=True)
class EditJdConditions:
    command_id: UUID
    expected_revision_id: UUID
    change: ConditionChange


def condition_change_payload(change: ConditionChange) -> list[dict[str, str | None]]:
    match change:
        case CreateCondition():
            return [{"action": "create_condition", "kind": change.kind.value, "text": change.text}]
        case ReviseCondition():
            fields: list[dict[str, str | None]] = []
            for item in change.changes:
                match item:
                    case ConditionTextChange():
                        fields.append({"field": "text", "value": item.text})
                    case ConditionKindChange():
                        fields.append({"field": "kind", "value": item.kind.value})
            return [
                {"action": "revise_condition", "condition_id": str(change.condition_id)},
                *fields,
            ]
        case DeleteCondition():
            return [{"action": "delete_condition", "condition_id": str(change.condition_id)}]
        case ReorderCondition():
            return [
                {
                    "action": "reorder_condition",
                    "condition_id": str(change.condition_id),
                    "before_condition_id": str(change.before_condition_id)
                    if change.before_condition_id
                    else None,
                }
            ]

"""Printable projection of one immutable formal JD revision."""

from html import escape
from uuid import UUID

from caliburn.features.job_description.capabilities import CapabilityKind
from caliburn.features.job_description.conditions import ConditionKind
from caliburn.features.job_description.models import JdProfile
from caliburn.features.job_description.tasks import DetailKind, WorkTask
from caliburn.features.job_description.work_queries import JdWorkRevision


def project_jd_export_html(profile: JdProfile, work: JdWorkRevision) -> str:
    """Escape plain JD text; no employee metadata, citations or candidate lookup exists here."""
    blocks = ["<h1>職務說明書</h1>"]
    for label, value in (
        ("職稱", profile.job_title),
        ("組織單位", profile.organization_unit),
        ("匯報對象", profile.reports_to),
        ("職務目的", profile.purpose),
    ):
        if value is not None:
            blocks.extend((_heading(2, label), _paragraph(value)))
    tasks_by_area: dict[UUID | None, list[WorkTask]] = {None: []}
    tasks_by_area.update((area.area_id, []) for area in work.areas)
    for task in work.tasks:
        # Never silently omit an orphan from an apparently complete export.
        tasks_by_area[task.area_id].append(task)
    capability_labels: dict[UUID, str] = {}
    for kind, label in ((CapabilityKind.KNOWLEDGE, "知識"), (CapabilityKind.SKILL, "技能")):
        for index, item in enumerate((item for item in work.capabilities if item.kind == kind), 1):
            capability_labels[item.capability_id] = f"{label} {index}" + (
                f"：{item.name}" if item.name else ""
            )
    if work.areas or work.tasks:
        blocks.append(_heading(2, "主要職責與工作任務"))
    for index, area in enumerate(work.areas, 1):
        blocks.append(_heading(3, f"職責 {index}" + (f"：{area.title}" if area.title else "")))
        if area.scope_text is not None:
            blocks.append(_paragraph(area.scope_text))
        blocks.extend(_tasks(tasks_by_area[area.area_id], work, capability_labels))
    if tasks_by_area[None]:
        blocks.append(_heading(3, "未歸屬任務"))
        blocks.extend(_tasks(tasks_by_area[None], work, capability_labels))
    for kind, label in ((CapabilityKind.KNOWLEDGE, "知識"), (CapabilityKind.SKILL, "技能")):
        items = [item for item in work.capabilities if item.kind == kind]
        if items:
            blocks.append(_heading(2, f"所需{label}"))
        for item in items:
            blocks.append(_heading(3, capability_labels[item.capability_id]))
            if item.description is not None:
                blocks.append(_paragraph(item.description))
    if work.collaborators:
        blocks.append(_heading(2, "主要協作對象"))
    for index, collaborator in enumerate(work.collaborators, 1):
        blocks.append(_heading(3, collaborator.name or f"協作對象 {index}"))
        if collaborator.scope_text is not None:
            blocks.append(_paragraph(collaborator.scope_text))
    if work.conditions:
        blocks.append(_heading(2, "工作條件與責任邊界"))
    labels = {
        ConditionKind.WORK_ENVIRONMENT: "工作環境",
        ConditionKind.SCHEDULE_TRAVEL: "工時與出差",
        ConditionKind.SHARED_AUTHORITY: "共通權限界線",
        ConditionKind.SHARED_COLLABORATION: "共通協作界線",
        ConditionKind.QUALIFICATION: "必要資格",
    }
    for condition in work.conditions:
        blocks.extend((_heading(3, labels[condition.kind]), _paragraph(condition.text)))
    if len(blocks) == 1:
        blocks.append(_paragraph("尚無已保存的職務內容"))
    return "\n".join(blocks)


def _heading(level: int, text: str) -> str:
    return f"<h{level}>{escape(text)}</h{level}>"


def _paragraph(text: str) -> str:
    return f"<p>{escape(text)}</p>"


def _tasks(tasks: list[WorkTask], work: JdWorkRevision, labels: dict[UUID, str]) -> list[str]:
    blocks = []
    kinds = {item.capability_id: item.kind for item in work.capabilities}
    for index, task in enumerate(tasks, 1):
        blocks.append(_heading(4, f"任務 {index}" + (f"：{task.title}" if task.title else "")))
        if task.description is not None:
            blocks.append(_paragraph(task.description))
        for kind, label in ((DetailKind.OUTCOME, "成果 O"), (DetailKind.REQUIREMENT, "執行要求 P")):
            details = [detail for detail in task.details if detail.kind == kind]
            if details:
                blocks.extend((_heading(5, label), "<ul>"))
                blocks.extend(f"<li>{escape(detail.text)}</li>" for detail in details)
                blocks.append("</ul>")
        for capability_kind, label in (
            (CapabilityKind.KNOWLEDGE, "知識 K"),
            (CapabilityKind.SKILL, "技能 S"),
        ):
            linked = [
                link.capability_id
                for link in work.task_links
                if link.task_id == task.task_id and kinds[link.capability_id] == capability_kind
            ]
            if linked:
                blocks.extend(
                    (_heading(5, label), _paragraph("；".join(labels[item] for item in linked)))
                )
    return blocks

"""Durable JD model aliases; domain object and citation identities remain UUIDs."""

from collections.abc import Collection
from uuid import UUID

from sqlalchemy import BigInteger, ForeignKey, Identity, Text, UniqueConstraint, select
from sqlalchemy.dialects.postgresql import insert
from sqlalchemy.ext.asyncio import AsyncSession
from sqlalchemy.orm import Mapped, mapped_column

from caliburn.adapters.database import Base


class JdModelReferenceRecord(Base):
    __tablename__ = "jd_model_references"
    __table_args__ = (UniqueConstraint("job_file_id", "canonical_ref"),)

    reference_number: Mapped[int] = mapped_column(
        BigInteger, Identity(always=True), primary_key=True
    )
    job_file_id: Mapped[UUID] = mapped_column(ForeignKey("job_files.job_file_id"))
    canonical_ref: Mapped[str] = mapped_column(Text)

    @property
    def model_ref(self) -> str:
        return f"{self.canonical_ref.rsplit('_', 1)[0]}_{self.reference_number}"


async def assign_references(
    session: AsyncSession, job_file_id: UUID, canonical_refs: Collection[str]
) -> dict[str, str]:
    """Never update/recycle an alias, including deleted or abandoned candidate objects."""
    if not canonical_refs:
        return {}
    query = select(JdModelReferenceRecord).where(
        JdModelReferenceRecord.job_file_id == job_file_id,
        JdModelReferenceRecord.canonical_ref.in_(canonical_refs),
    )
    rows = list(await session.scalars(query))
    existing = {row.canonical_ref for row in rows}
    missing = sorted(set(canonical_refs) - existing)
    if missing:
        await session.execute(
            insert(JdModelReferenceRecord)
            .values([{"job_file_id": job_file_id, "canonical_ref": ref} for ref in missing])
            .on_conflict_do_nothing(index_elements=["job_file_id", "canonical_ref"])
        )
        # A separate SELECT sees a concurrent inserter after ON CONFLICT has waited.
        rows = list(await session.scalars(query))
    return {row.canonical_ref: row.model_ref for row in rows}


async def read_references(
    session: AsyncSession, job_file_id: UUID, reference_numbers: Collection[int]
) -> dict[str, str]:
    if not reference_numbers:
        return {}
    rows = await session.scalars(
        select(JdModelReferenceRecord).where(
            JdModelReferenceRecord.job_file_id == job_file_id,
            JdModelReferenceRecord.reference_number.in_(reference_numbers),
        )
    )
    return {row.model_ref: row.canonical_ref for row in rows}

"""Pure JD profile values and explicit partial-edit intent; no storage or transport."""

from dataclasses import dataclass, replace
from enum import StrEnum
from uuid import UUID


class JdCommandConflictError(ValueError):
    """A JD command identity was reused with different intent."""


class StaleJdRevisionError(ValueError):
    """A new edit no longer targets the current formal JD revision."""


class InvalidProfileChangeError(ValueError):
    """The requested profile changes cannot be applied as one unambiguous operation."""


class ProfileField(StrEnum):
    JOB_TITLE = "job_title"
    ORGANIZATION_UNIT = "organization_unit"
    REPORTS_TO = "reports_to"
    PURPOSE = "purpose"


@dataclass(frozen=True, slots=True)
class JdProfile:
    job_title: str | None = None
    organization_unit: str | None = None
    reports_to: str | None = None
    purpose: str | None = None


@dataclass(frozen=True, slots=True)
class SetProfileField:
    field: ProfileField
    value: str

    def __post_init__(self) -> None:
        if not self.value.strip() or "\x00" in self.value:
            raise InvalidProfileChangeError("A set value must contain nonblank text without NUL")


@dataclass(frozen=True, slots=True)
class ClearProfileField:
    field: ProfileField


type ProfileChange = SetProfileField | ClearProfileField


@dataclass(frozen=True, slots=True)
class ReviseJdProfile:
    command_id: UUID
    expected_revision_id: UUID
    changes: tuple[ProfileChange, ...]

    def __post_init__(self) -> None:
        fields = [change.field for change in self.changes]
        if not fields or len(fields) != len(set(fields)):
            raise InvalidProfileChangeError("Choose at least one field, and change each field once")


@dataclass(frozen=True, slots=True)
class JdProfileRevision:
