        if isinstance(change, SetProfileField)
        else {"action": "clear_field", "field": change.field.value}
        for change in changes
    ]

"""Apply one precise source-owner edit; external source qualification stays in workflows."""

from uuid import uuid4

from caliburn.features.job_description.sources import (
    AddJdSource,
    AlignJdSource,
    InterviewSource,
    InvalidJdSourceError,
    JdSource,
    JdSourceReference,
    RemoveJdSource,
    ReviseJdSources,
    add_source_reference,
    align_source_reference,
)


def apply_source_changes(
    references: tuple[JdSourceReference, ...], command: ReviseJdSources
) -> tuple[JdSourceReference, ...]:
    result = references
    for change in command.changes:
        if isinstance(change, AddJdSource):
            result = add_source_reference(
                result, JdSourceReference(uuid4(), command.target, change.source)
            )
            continue
        reference = next((ref for ref in result if ref.citation_id == change.citation_id), None)
        if reference is None or reference.target != command.target:
            raise InvalidJdSourceError("The citation does not belong to the selected JD target")
        if isinstance(change, RemoveJdSource):
            result = tuple(ref for ref in result if ref.citation_id != reference.citation_id)
        elif isinstance(change, AlignJdSource):
            aligned = align_source_reference(reference, change.source)
            result = tuple(
                aligned if ref.citation_id == reference.citation_id else ref for ref in result
            )
    return result


def source_change_payload(command: ReviseJdSources) -> dict[str, object]:
    """Typed command values only, with explicit actions for reliable original-result comparison."""
    changes: list[dict[str, object]] = []
    for change in command.changes:
        if isinstance(change, AddJdSource):
            changes.append({"action": "add_source", "source": _source_payload(change.source)})
        elif isinstance(change, RemoveJdSource):
            changes.append({"action": "remove_source", "citation_id": str(change.citation_id)})
        else:
            changes.append(
                {
                    "action": "confirm_reference_alignment",
                    "citation_id": str(change.citation_id),
                    "source": _source_payload(change.source),
                }
            )
    target = command.target
    return {
        "target": {
            "kind": target.kind.value,
            "item_id": str(target.item_id) if target.item_id is not None else None,
            "field": target.field.value if target.field is not None else None,
            "task_id": str(target.task_id) if target.task_id is not None else None,
        },
        "changes": changes,
    }


def _source_payload(source: JdSource) -> dict[str, str]:
    if isinstance(source, InterviewSource):
        return {"kind": "interview", "source_id": str(source.source_id)}
    return {
        "kind": source.layer.value,
        "snapshot_id": str(source.snapshot_id),
        "object_id": str(source.object_id),
        "revision_id": str(source.revision_id),
    }

"""Semantic JD source owners; arrangement and child evidence are not inherited content."""

from caliburn.features.job_description.models import JdProfile, ProfileField
from caliburn.features.job_description.sources import JdSourceTarget, SourceTargetKind
from caliburn.features.job_description.work_queries import JdWorkRevision


def source_target_contents(
    profile: JdProfile, work: JdWorkRevision
) -> dict[JdSourceTarget, tuple[str | None, ...]]:
    result: dict[JdSourceTarget, tuple[str | None, ...]] = {
        JdSourceTarget(SourceTargetKind.PROFILE_FIELD, field=field): (getattr(profile, field),)
        for field in ProfileField
    }
    for area in work.areas:
        result[JdSourceTarget(SourceTargetKind.AREA, area.area_id)] = (area.title, area.scope_text)
    for task in work.tasks:
        result[JdSourceTarget(SourceTargetKind.TASK, task.task_id)] = (task.title, task.description)
        for detail in task.details:
            result[
                JdSourceTarget(SourceTargetKind.DETAIL, detail.detail_id, task_id=task.task_id)
            ] = (
                detail.kind.value,
                detail.text,
            )
    for capability in work.capabilities:
        result[JdSourceTarget(SourceTargetKind.CAPABILITY, capability.capability_id)] = (
            capability.kind.value,
            capability.name,
            capability.description,
        )
    tasks = {item.task_id: item for item in work.tasks}
    capabilities = {item.capability_id: item for item in work.capabilities}
    for link in work.task_links:
        task = tasks[link.task_id]
        capability = capabilities[link.capability_id]
        # This evidence supports the use of this definition in this task, not its position.
        result[
            JdSourceTarget(
                SourceTargetKind.TASK_CAPABILITY, link.capability_id, task_id=link.task_id
            )
        ] = (
            task.title,
            task.description,
            capability.kind.value,
            capability.name,
            capability.description,
        )
    for collaborator in work.collaborators:
        result[JdSourceTarget(SourceTargetKind.COLLABORATOR, collaborator.collaborator_id)] = (
            collaborator.name,
            collaborator.scope_text,
        )
    for condition in work.conditions:
        result[JdSourceTarget(SourceTargetKind.CONDITION, condition.condition_id)] = (
            condition.kind.value,
            condition.text,
        )
    return result

"""JD-owned direct evidence, distinct from source content and model-visible locators."""

from collections.abc import Mapping
from dataclasses import dataclass, replace
from enum import StrEnum
from uuid import UUID

from caliburn.features.job_description.models import ProfileField


class InvalidJdSourceError(ValueError):
    """Evidence must keep its precise JD owner and original source identity."""


class SourceTargetKind(StrEnum):
    PROFILE_FIELD = "profile_field"
    AREA = "area"
    TASK = "task"
    DETAIL = "detail"
    CAPABILITY = "capability"
    COLLABORATOR = "collaborator"
    CONDITION = "condition"
    TASK_CAPABILITY = "task_capability"


@dataclass(frozen=True, slots=True)
class JdSourceTarget:
    kind: SourceTargetKind
    item_id: UUID | None = None
    field: ProfileField | None = None
    task_id: UUID | None = None

    def __post_init__(self) -> None:
        if self.kind == SourceTargetKind.PROFILE_FIELD:
            valid = self.field is not None and self.item_id is None and self.task_id is None
        else:
            needs_task = self.kind in {SourceTargetKind.DETAIL, SourceTargetKind.TASK_CAPABILITY}
            valid = (
                self.field is None
                and self.item_id is not None
                and (self.task_id is not None) == needs_task
            )
        if not valid:
            raise InvalidJdSourceError("The source target has missing or unrelated identity fields")


@dataclass(frozen=True, slots=True)
class InterviewSource:
    # Pending current_input retains this identity when the same text becomes formal.
    source_id: UUID


class MemorySourceLayer(StrEnum):
    WORK_SITUATION = "work_situation"
    WORK_UNDERSTANDING = "work_understanding"


@dataclass(frozen=True, slots=True)
class MemorySource:
    layer: MemorySourceLayer
    snapshot_id: UUID
    object_id: UUID
    revision_id: UUID


type JdSource = InterviewSource | MemorySource
type SourceTargetContents = Mapping[JdSourceTarget, tuple[str | None, ...]]


@dataclass(frozen=True, slots=True)
class JdSourceReference:
    citation_id: UUID
    target: JdSourceTarget
    source: JdSource
    needs_review: bool = False
    # None is only an unpersisted addition/alignment; storage binds the new JD revision.
    reviewed_revision_id: UUID | None = None


def same_source_identity(left: JdSource, right: JdSource) -> bool:
    match left, right:
        case InterviewSource(), InterviewSource():
            return left.source_id == right.source_id
        case MemorySource(), MemorySource():
            return left.layer == right.layer and left.object_id == right.object_id
        case _:
            return False


def carry_source_references(
    references: tuple[JdSourceReference, ...],
    before: SourceTargetContents,
    after: SourceTargetContents,
) -> tuple[JdSourceReference, ...]:
    """Retain evidence on surviving targets without silently confirming changed text."""
    carried = []
    for reference in references:
        if reference.target not in before:
            raise InvalidJdSourceError("Existing evidence has no owner in its original JD")
        if reference.target in after:
            carried.append(
                replace(
                    reference,
                    needs_review=(
                        reference.needs_review
                        or before[reference.target] != after[reference.target]
                    ),
                )
            )
    return tuple(carried)


def add_source_reference(
    references: tuple[JdSourceReference, ...], new: JdSourceReference
) -> tuple[JdSourceReference, ...]:
    """Adding the same source again cannot refresh its revision or review status."""
    if any(
        reference.citation_id == new.citation_id and reference != new for reference in references
    ):
        raise InvalidJdSourceError("A citation identity cannot select different evidence")
    for reference in references:
        if reference.target == new.target and same_source_identity(reference.source, new.source):
            return references
    return (*references, new)


def align_source_reference(reference: JdSourceReference, source: JdSource) -> JdSourceReference:
    """The workflow must first resolve a permitted current source for the same identity."""
    if not same_source_identity(reference.source, source):
        raise InvalidJdSourceError("Alignment cannot replace the original source identity")
    if reference.source == source and not reference.needs_review:
        return reference
    return replace(reference, source=source, needs_review=False, reviewed_revision_id=None)


@dataclass(frozen=True, slots=True)
class AddJdSource:
    source: JdSource


@dataclass(frozen=True, slots=True)
class RemoveJdSource:
    citation_id: UUID


@dataclass(frozen=True, slots=True)
class AlignJdSource:
    citation_id: UUID
    source: JdSource


type JdSourceChange = AddJdSource | RemoveJdSource | AlignJdSource


@dataclass(frozen=True, slots=True)
class ReviseJdSources:
    command_id: UUID
    expected_revision_id: UUID
    target: JdSourceTarget
    changes: tuple[JdSourceChange, ...]

    def __post_init__(self) -> None:
        validate_source_changes(self.changes)


def validate_source_changes(changes: tuple[JdSourceChange, ...]) -> None:
    if not changes:
        raise InvalidJdSourceError("Choose at least one source change")
    changed: set[UUID] = set()
    added: list[JdSource] = []
    for change in changes:
        if isinstance(change, AddJdSource):
            if any(same_source_identity(change.source, source) for source in added):
                raise InvalidJdSourceError("Add each source only once")
            added.append(change.source)
        else:
            if change.citation_id in changed:
                raise InvalidJdSourceError("Change each existing citation only once")
            changed.add(change.citation_id)

"""Pure task editing, stable identities, independent detail order and scope checks."""

from dataclasses import replace
from uuid import UUID, uuid4

from caliburn.features.job_description.tasks import (
    AddTaskDetail,
    CreateTask,
    DeleteTask,
    DetailKind,
    InvalidTaskChangeError,
    MoveTask,
    RemoveTaskDetail,
    ReorderTaskDetail,
    ReviseTask,
    ReviseTaskDetail,
    SetTaskField,
    TaskChange,
    TaskDetail,
    TaskEdit,
    TaskField,
    TaskTargetNotFoundError,
    WorkTask,
)


def _ordered_details(details: tuple[TaskDetail, ...]) -> tuple[TaskDetail, ...]:
    return tuple(detail for kind in DetailKind for detail in details if detail.kind == kind)


def order_tasks(tasks: tuple[WorkTask, ...], area_ids: tuple[UUID, ...]) -> tuple[WorkTask, ...]:
    """Canonical collection order; positions inside each group remain independent."""
    if any(task.area_id is not None and task.area_id not in area_ids for task in tasks):
        raise TaskTargetNotFoundError("Task group is not in this JD")
    return tuple(task for area_id in (None, *area_ids) for task in tasks if task.area_id == area_id)


def _revise(task: WorkTask, changes: tuple[TaskChange, ...]) -> WorkTask:
    title, description = task.title, task.description
    details = task.details
    for change in changes:
        match change:
            case SetTaskField():
                if change.field == TaskField.TITLE:
                    title = change.value
                else:
                    description = change.value
            case AddTaskDetail():
                details = (*details, TaskDetail(uuid4(), change.kind, change.text))
            case ReviseTaskDetail() | RemoveTaskDetail():
                if not any(detail.detail_id == change.detail_id for detail in details):
                    raise TaskTargetNotFoundError("Detail is not in the selected task")
                if isinstance(change, RemoveTaskDetail):
                    details = tuple(d for d in details if d.detail_id != change.detail_id)
                else:
                    details = tuple(
                        replace(d, text=change.text) if d.detail_id == change.detail_id else d
                        for d in details
                    )
    revised = replace(task, title=title, description=description, details=_ordered_details(details))
    return replace(revised, content_revision_id=uuid4()) if revised != task else task


def _reorder_detail(task: WorkTask, edit: ReorderTaskDetail) -> WorkTask:
    target = next((d for d in task.details if d.detail_id == edit.detail_id), None)
    if target is None:
        raise TaskTargetNotFoundError("Detail is not in the selected task")
    if edit.before_detail_id == target.detail_id:
        return task
    same_kind = tuple(d for d in task.details if d.kind == target.kind and d != target)
    index = len(same_kind)
    if edit.before_detail_id is not None:
        neighbour = next((d for d in task.details if d.detail_id == edit.before_detail_id), None)
        if neighbour is None:
            raise TaskTargetNotFoundError("Detail ordering neighbour is not in this task")
        if neighbour.kind != target.kind:
            raise InvalidTaskChangeError("Outcomes and requirements have separate order")
        index = same_kind.index(neighbour)
    ordered = (*same_kind[:index], target, *same_kind[index:])
    details = _ordered_details((*ordered, *(d for d in task.details if d.kind != target.kind)))
    return (
        replace(task, details=details, content_revision_id=uuid4())
        if details != task.details
        else task
    )


def apply_task_edit(
    tasks: tuple[WorkTask, ...],
    area_ids: tuple[UUID, ...],
    edit: TaskEdit,
) -> tuple[tuple[WorkTask, ...], WorkTask | None]:
    """Compute the complete next collection before writes; return changed content only."""
    if (
        isinstance(edit, CreateTask | MoveTask)
        and edit.area_id is not None
        and edit.area_id not in area_ids
    ):
        raise TaskTargetNotFoundError("Destination responsibility group is not in this JD")
    if isinstance(edit, CreateTask):
        details = tuple(
            TaskDetail(uuid4(), kind, text)
            for kind, texts in (
                (DetailKind.OUTCOME, edit.outcomes),
                (DetailKind.REQUIREMENT, edit.requirements),
            )
            for text in texts
        )
        created = WorkTask(uuid4(), uuid4(), edit.area_id, edit.title, edit.description, details)
        return order_tasks((*tasks, created), area_ids), created
    target = next((task for task in tasks if task.task_id == edit.task_id), None)
    if target is None:
        raise TaskTargetNotFoundError("Task is not in the selected JD")
    if isinstance(edit, DeleteTask):
        return tuple(task for task in tasks if task != target), None
    if isinstance(edit, MoveTask):
        revised = _revise(target, edit.changes)
        moved = replace(revised, area_id=edit.area_id)
        remaining = tuple(task for task in tasks if task.task_id != target.task_id)
        destination = tuple(task for task in remaining if task.area_id == edit.area_id)
        if edit.before_task_id == target.task_id:
            if target.area_id != edit.area_id:
                raise InvalidTaskChangeError("A moved task cannot be its own destination neighbour")
            result = tuple(moved if task == target else task for task in tasks)
        else:
            index = len(destination)
            if edit.before_task_id is not None:
                neighbour = next((t for t in destination if t.task_id == edit.before_task_id), None)
                if neighbour is None:
                    raise TaskTargetNotFoundError("Ordering neighbour must belong to destination")
                index = destination.index(neighbour)
            result = order_tasks(
                (
                    *(task for task in remaining if task.area_id != edit.area_id),
                    *destination[:index],
                    moved,
                    *destination[index:],
                ),
                area_ids,
            )
        return result, moved if revised.content_revision_id != target.content_revision_id else None
    revised = (
        _revise(target, edit.changes)
        if isinstance(edit, ReviseTask)
        else _reorder_detail(target, edit)
    )
    return (
        tuple(revised if task == target else task for task in tasks),
        revised if revised != target else None,
    )


def detach_area_tasks(tasks: tuple[WorkTask, ...], area_id: UUID) -> tuple[WorkTask, ...]:
    """Append removed group's tasks to unassigned, keeping all identities and relative order."""
    return (
        *(task for task in tasks if task.area_id is None),
        *(replace(task, area_id=None) for task in tasks if task.area_id == area_id),
        *(task for task in tasks if task.area_id is not None and task.area_id != area_id),
    )


def _change_payload(change: TaskChange) -> dict[str, object]:
    match change:
        case SetTaskField():
            return {"action": "set_field", "field": change.field.value, "value": change.value}
        case AddTaskDetail():
            return {"action": "add_detail", "kind": change.kind.value, "text": change.text}
        case ReviseTaskDetail():
            return {
                "action": "revise_detail",
                "detail_id": str(change.detail_id),
                "text": change.text,
            }
        case RemoveTaskDetail():
            return {"action": "remove_detail", "detail_id": str(change.detail_id)}


def task_edit_payload(edit: TaskEdit) -> dict[str, object]:
    """JSON-compatible original intention; generated IDs are results, never replay inputs."""
    match edit:
        case CreateTask():
            return {
                "action": "create_task",
                "area_id": str(edit.area_id) if edit.area_id else None,
                "title": edit.title,
                "description": edit.description,
                "outcomes": list(edit.outcomes),
                "requirements": list(edit.requirements),
            }
        case ReviseTask():
            return {
                "action": "revise_task",
                "task_id": str(edit.task_id),
                "changes": [_change_payload(change) for change in edit.changes],
            }
        case MoveTask():
            return {
                "action": "move_task",
                "task_id": str(edit.task_id),
                "area_id": str(edit.area_id) if edit.area_id else None,
                "before_task_id": str(edit.before_task_id) if edit.before_task_id else None,
                "changes": [_change_payload(change) for change in edit.changes],
            }
        case ReorderTaskDetail():
            return {
                "action": "reorder_detail",
                "task_id": str(edit.task_id),
                "detail_id": str(edit.detail_id),
                "before_detail_id": str(edit.before_detail_id) if edit.before_detail_id else None,
            }
        case DeleteTask():
            return {"action": "delete_task", "task_id": str(edit.task_id)}

"""Task values and bounded intentions; no HTTP, database or provider dependencies."""

from dataclasses import dataclass
from enum import StrEnum
from uuid import UUID


class InvalidTaskChangeError(ValueError):
    """An edit has ambiguous effects or would leave invalid task content."""


class TaskTargetNotFoundError(ValueError):
    """A selected task, detail, group or ordering neighbour is not in scope."""


class TaskField(StrEnum):
    TITLE = "title"
    DESCRIPTION = "description"


class DetailKind(StrEnum):
    OUTCOME = "outcome"
    REQUIREMENT = "requirement"


def validate_text(value: str) -> None:
    if not value.strip() or "\x00" in value:
        raise InvalidTaskChangeError("Task text must be nonblank without NUL")


def validate_task_text(title: str | None, description: str | None) -> None:
    if title is None and description is None:
        raise InvalidTaskChangeError("A task needs a title or meaningful description")
    for value in (title, description):
        if value is not None:
            validate_text(value)


@dataclass(frozen=True, slots=True)
class TaskDetail:
    detail_id: UUID
    kind: DetailKind
    text: str

    def __post_init__(self) -> None:
        validate_text(self.text)


@dataclass(frozen=True, slots=True)
class WorkTask:
    task_id: UUID
    content_revision_id: UUID
    area_id: UUID | None
    title: str | None
    description: str | None
    details: tuple[TaskDetail, ...]

    def __post_init__(self) -> None:
        validate_task_text(self.title, self.description)
        if len({detail.detail_id for detail in self.details}) != len(self.details):
            raise InvalidTaskChangeError("A task cannot contain a detail twice")


@dataclass(frozen=True, slots=True)
class JdTasksRevision:
    revision_id: UUID
    tasks: tuple[WorkTask, ...]


@dataclass(frozen=True, slots=True)
class SetTaskField:
    field: TaskField
    value: str | None


@dataclass(frozen=True, slots=True)
class AddTaskDetail:
    kind: DetailKind
    text: str


@dataclass(frozen=True, slots=True)
class ReviseTaskDetail:
    detail_id: UUID
    text: str


@dataclass(frozen=True, slots=True)
class RemoveTaskDetail:
    detail_id: UUID


type TaskChange = SetTaskField | AddTaskDetail | ReviseTaskDetail | RemoveTaskDetail


@dataclass(frozen=True, slots=True)
class CreateTask:
    area_id: UUID | None
    title: str | None
    description: str | None
    outcomes: tuple[str, ...]
    requirements: tuple[str, ...]

    def __post_init__(self) -> None:
        validate_task_text(self.title, self.description)
        for text in (*self.outcomes, *self.requirements):
            validate_text(text)


def validate_changes(changes: tuple[TaskChange, ...]) -> None:
    keys: set[tuple[str, str]] = set()
    for change in changes:
        if isinstance(change, AddTaskDetail):
            validate_text(change.text)
            continue
        if isinstance(change, SetTaskField):
            if change.value is not None:
                validate_text(change.value)
            key = ("field", change.field.value)
        else:
            if isinstance(change, ReviseTaskDetail):
                validate_text(change.text)
            key = ("detail", str(change.detail_id))
        if key in keys:
            raise InvalidTaskChangeError("Change each field or existing detail only once")
        keys.add(key)


@dataclass(frozen=True, slots=True)
class ReviseTask:
    task_id: UUID
    changes: tuple[TaskChange, ...]

    def __post_init__(self) -> None:
        if not self.changes:
            raise InvalidTaskChangeError("Choose at least one task change")
        validate_changes(self.changes)


@dataclass(frozen=True, slots=True)
class MoveTask:
    task_id: UUID
    area_id: UUID | None
    before_task_id: UUID | None
    changes: tuple[TaskChange, ...] = ()

    def __post_init__(self) -> None:
        validate_changes(self.changes)


@dataclass(frozen=True, slots=True)
class ReorderTaskDetail:
    task_id: UUID
    detail_id: UUID
    before_detail_id: UUID | None


@dataclass(frozen=True, slots=True)
class DeleteTask:
    task_id: UUID


type TaskEdit = CreateTask | ReviseTask | MoveTask | ReorderTaskDetail | DeleteTask


@dataclass(frozen=True, slots=True)
class EditJdTasks:
    command_id: UUID
    expected_revision_id: UUID
    change: TaskEdit

