"""Pure, all-or-none edits of one caller-bound Memory Markdown body."""

import re
from dataclasses import dataclass

from caliburn.adapters.v4a_parser import V4ASyntaxError, parse_body_diff
from caliburn.features.work_memory.body_matching import (
    BodyEditError,
    BodyMatchPolicy,
    locate_hunk,
)


@dataclass(frozen=True, slots=True)
class _LineEdit:
    start: int
    stop: int
    inserted_lines: tuple[str, ...]


DEFAULT_BODY_MATCH_POLICY = BodyMatchPolicy()


def apply_body_diff(
    body: str, diff: str, *, policy: BodyMatchPolicy = DEFAULT_BODY_MATCH_POLICY
) -> str:
    """Return revised body; never perform filesystem or persistence operations."""
    if len(body) > policy.max_body_characters or len(diff) > policy.max_diff_characters:
        raise BodyEditError(
            "patch_limit_exceeded", "Body or diff exceeds the configured edit limit"
        )
    if not body.strip():
        raise BodyEditError("invalid_patch", "Update requires a nonblank source body")
    try:
        hunks = parse_body_diff(diff)
    except V4ASyntaxError as error:
        raise BodyEditError("invalid_patch", str(error)) from error
    if len(hunks) > policy.max_hunks:
        raise BodyEditError("patch_limit_exceeded", "Too many hunks; use smaller edits")
    # Only LF/CRLF are line separators. Other Unicode separators are source text.
    raw_lines = split_body_lines(body)
    lines = tuple(_line_content(line) for line in raw_lines)
    scan_characters = sum(
        len(lines) * sum(len(line) for line in (*hunk.context, *hunk.anchors))
        + len(body) * (len(hunk.context) + len(hunk.anchors))
        for hunk in hunks
    )
    if scan_characters > policy.max_scan_characters:
        raise BodyEditError(
            "patch_limit_exceeded", "Complete ambiguity scan exceeds the limit; use smaller hunks"
        )
    edits: list[_LineEdit] = []
    cursor = 0
    for number, hunk in enumerate(hunks, 1):
        start = locate_hunk(lines, hunk, cursor=cursor, hunk_number=number, policy=policy)
        for chunk in hunk.chunks:
            edit_start = start + chunk.original_index
            edits.append(
                _LineEdit(edit_start, edit_start + len(chunk.deleted_lines), chunk.inserted_lines)
            )
        cursor = start + len(hunk.context)
    # All syntax and locations have succeeded before any returned body is built.
    result: list[str] = []
    cursor = 0
    for edit in edits:
        result.extend(raw_lines[cursor : edit.start])
        if lines[edit.start : edit.stop] == edit.inserted_lines:
            result.extend(raw_lines[edit.start : edit.stop])
            cursor = edit.stop
            continue
        newline = _local_newline(raw_lines, edit.start)
        inserted = [line + newline for line in edit.inserted_lines]
        if inserted and edit.stop == len(raw_lines) and not body.endswith("\n"):
            inserted[-1] = inserted[-1][: -len(newline)]
        if inserted and result and not result[-1].endswith("\n"):
            result[-1] += newline
        result.extend(inserted)
        cursor = edit.stop
    result.extend(raw_lines[cursor:])
    revised = "".join(result)
    if len(revised) > policy.max_body_characters:
        raise BodyEditError(
            "patch_limit_exceeded", "Revised body exceeds the configured edit limit"
        )
    if not revised.strip():
        raise BodyEditError(
            "invalid_patch", "Body must remain nonblank; use delete for object removal"
        )
    return revised


def split_body_lines(body: str) -> list[str]:
    """Preserve exact source lines; Unicode separators and lone CR are content, not LF."""
    return re.findall(r"[^\n]*\n|[^\n]+$", body)


def _line_content(line: str) -> str:
    return line[:-2] if line.endswith("\r\n") else line.removesuffix("\n")


def _local_newline(lines: list[str], start: int) -> str:
    if start < len(lines) and lines[start].endswith("\n"):
        return "\r\n" if lines[start].endswith("\r\n") else "\n"
    if start and lines[start - 1].endswith("\n"):
        return "\r\n" if lines[start - 1].endswith("\r\n") else "\n"
    return "\n"

"""Bounded, ambiguity-rejecting whole-line location for Memory body hunks."""

from dataclasses import dataclass
from typing import Literal

from rapidfuzz.distance import Levenshtein

from caliburn.adapters.v4a_parser import V4AHunk

type BodyEditErrorCode = Literal[
    "invalid_patch", "patch_context_not_found", "ambiguous_patch_context", "patch_limit_exceeded"
]


@dataclass(frozen=True, slots=True)
class BodyMatch:
    start_line: int
    end_line: int
    excerpt: str


class BodyEditError(ValueError):
    """Safe typed rejection; candidate locations are diagnostic, not write handles."""

    def __init__(
        self,
        code: BodyEditErrorCode,
        message: str,
        *,
        hunk_number: int | None = None,
        candidates: tuple[BodyMatch, ...] = (),
    ) -> None:
        super().__init__(message)
        self.code = code
        self.hunk_number = hunk_number
        self.candidates = candidates


@dataclass(frozen=True, slots=True)
class BodyMatchPolicy:
    """App-owned bounded engineering defaults, not model-supplied tool arguments."""

    line_similarity: float = 0.90
    minimum_fuzzy_line_characters: int = 10
    max_body_characters: int = 2_000_000
    max_diff_characters: int = 64_000
    max_hunks: int = 128
    max_scan_characters: int = 20_000_000

    def __post_init__(self) -> None:
        if not 0 < self.line_similarity <= 1:
            raise ValueError("Line similarity must be within (0, 1]")
        if (
            min(
                self.minimum_fuzzy_line_characters,
                self.max_body_characters,
                self.max_diff_characters,
                self.max_hunks,
                self.max_scan_characters,
            )
            < 1
        ):
            raise ValueError("Body edit limits must be positive")


def locate_hunk(
    lines: tuple[str, ...],
    hunk: V4AHunk,
    *,
    cursor: int,
    hunk_number: int,
    policy: BodyMatchPolicy,
) -> int:
    """Return a zero-based unique start; do not prefer exact over qualified fuzzy.

    Anchors only advance the search floor. Every qualifying context at or after
    that floor counts, including overlapping candidates and unequal scores.
    EOF is a hard boundary, never a fallback search through the body.
    """
    for anchor_index, anchor in enumerate(hunk.anchors):
        if anchor_index == 0 and any(line.strip() == anchor.strip() for line in lines[:cursor]):
            # A repeated parent header names earlier context without rewinding.
            # Retain the full current floor, so later duplicates still count.
            continue
        # Choosing the earliest qualifying anchor retains every later possible
        # context; a repeated anchor cannot silently suppress another match.
        position = next(
            (
                index
                for index in range(cursor, len(lines))
                if lines[index].strip() == anchor.strip()
            ),
            None,
        )
        if position is None:
            raise BodyEditError(
                "patch_context_not_found", "Source anchor was not found", hunk_number=hunk_number
            )
        cursor = position + 1

    width = len(hunk.context)
    last_start = len(lines) - width
    starts = (
        range(max(cursor, last_start), last_start + 1)
        if hunk.end_of_file
        else range(cursor, last_start + 1)
    )
    target = tuple(line.strip() for line in hunk.context)
    normalized = tuple(line.strip() for line in lines)
    matches: list[BodyMatch] = []
    for start in starts:
        if all(
            _qualifies(expected, normalized[start + offset], policy)
            for offset, expected in enumerate(target)
        ):
            matches.append(
                BodyMatch(start + 1, start + width, "\n".join(lines[start : start + width])[:320])
            )
            if len(matches) == 2:
                raise BodyEditError(
                    "ambiguous_patch_context",
                    "At least two source contexts qualify; add distinguishing real context",
                    hunk_number=hunk_number,
                    candidates=tuple(matches),
                )
    if not matches:
        raise BodyEditError(
            "patch_context_not_found",
            "No qualifying source context; read the body and use complete source lines",
            hunk_number=hunk_number,
        )
    return matches[0].start_line - 1


def _qualifies(expected: str, actual: str, policy: BodyMatchPolicy) -> bool:
    if expected == actual:
        return True
    if min(len(expected), len(actual)) < policy.minimum_fuzzy_line_characters:
        return False
    # A per-line gate prevents a long identical context from hiding a completely
    # wrong short heading, responsibility, frequency, or deletion line.
    return (
        Levenshtein.normalized_similarity(expected, actual, score_cutoff=policy.line_similarity)
        >= policy.line_similarity
    )

"""Memory-owned original operation results, not a generic receipt framework."""

import hashlib
import json
from uuid import UUID

from sqlalchemy.ext.asyncio import AsyncSession

from caliburn.features.work_memory import batch_persistence
from caliburn.features.work_memory.candidates import (
    CreateMemoryObject,
    MemoryBatchPosition,
    MemoryCommandConflictError,
    MemoryEdit,
    ReviseMemoryObject,
)
from caliburn.features.work_memory.revisions import MemoryLayer


def position_fields(position: MemoryBatchPosition) -> dict[str, str]:
    return {
        "job_file_id": str(position.job_file_id),
        "execution_id": str(position.execution_id),
        "generation_id": str(position.generation_id),
        "stage_id": str(position.stage_id),
        "phase": position.phase.value,
        "position_id": str(position.position_id),
    }


def result_position(payload: dict[str, object]) -> MemoryBatchPosition:
    return MemoryBatchPosition(
        stored_uuid(payload, "job_file_id"),
        stored_uuid(payload, "execution_id"),
        stored_uuid(payload, "generation_id"),
        stored_uuid(payload, "stage_id"),
        MemoryLayer(stored_text(payload, "phase")),
        stored_uuid(payload, "position_id"),
    )


def stored_text(payload: dict[str, object], key: str) -> str:
    value = payload.get(key)
    if not isinstance(value, str):
        raise MemoryCommandConflictError("The saved operation result is incomplete")
    return value


def stored_uuid(payload: dict[str, object], key: str) -> UUID:
    return UUID(stored_text(payload, key))


def edit_payload(command: MemoryEdit) -> dict[str, object]:
    payload: dict[str, object] = {
        "position": position_fields(command.position),
        "layer": command.layer.value,
    }
    if isinstance(command, CreateMemoryObject):
        payload.update(
            {
                "action": "create",
                "title": command.content.title,
                "description": command.content.description,
                "body": command.content.body,
                "reference_ids": sorted(str(identity) for identity in command.reference_ids),
            }
        )
    else:
        payload["object_id"] = str(command.object_id)
        payload["action"] = "revise" if isinstance(command, ReviseMemoryObject) else "delete"
        if isinstance(command, ReviseMemoryObject):
            if command.content_changes is not None:
                payload["content_changes"] = {
                    "title": command.content_changes.title,
                    "description": command.content_changes.description,
                    "body": command.content_changes.body,
                }
            if command.reference_changes is not None:
                payload["reference_changes"] = {
                    "add": sorted(str(identity) for identity in command.reference_changes.add),
                    "remove": sorted(
                        str(identity) for identity in command.reference_changes.remove
                    ),
                }
    # Native-request retention belongs to execution recovery; the domain receipt
    # needs equality, not another copy of potentially long Markdown.
    digest = hashlib.sha256(
        json.dumps(payload, sort_keys=True, ensure_ascii=False, separators=(",", ":")).encode(
            "utf-8"
        )
    ).hexdigest()
    return {"position": position_fields(command.position), "intent_digest": digest}


async def recover(
    session: AsyncSession,
    job_file_id: UUID,
    execution_id: UUID,
    command_id: UUID,
    kind: str,
    payload: dict[str, object],
) -> dict[str, object] | None:
    record = await batch_persistence.read_operation(session, job_file_id, command_id)
    if record is None:
        return None
    if (
        record.execution_id != execution_id
        or record.kind != kind
        or record.request_payload != payload
    ):
        raise MemoryCommandConflictError("command_id was used for another Memory operation")
    result = record.result_payload
    if not isinstance(result, dict) or not all(isinstance(key, str) for key in result):
        raise MemoryCommandConflictError("The saved operation result is not an object")
    return {key: value for key, value in result.items()}


async def record_result(
    session: AsyncSession,
    position: MemoryBatchPosition,
    command_id: UUID,
    kind: str,
    payload: dict[str, object],
    *,
    object_id: UUID | None = None,
    snapshot_id: UUID | None = None,
) -> None:
    result: dict[str, object] = dict(position_fields(position))
    if object_id is not None:
        result["object_id"] = str(object_id)
    if snapshot_id is not None:
        result["snapshot_id"] = str(snapshot_id)
    session.add(
        batch_persistence.MemoryOperationRecord(
            job_file_id=position.job_file_id,
            execution_id=position.execution_id,
            command_id=command_id,
            kind=kind,
            request_payload=payload,
            result_payload=result,
        )
    )
    await session.flush()

"""Current candidate bindings and immutable publication reads use distinct projections."""

from uuid import UUID

from sqlalchemy.ext.asyncio import AsyncSession

from caliburn.features.work_memory import batch_persistence, position_persistence
from caliburn.features.work_memory.candidates import (
    MemoryBatchPosition,
    MemoryCandidateObject,
    MemoryCandidateStateError,
    MemorySnapshot,
    require_layer_read,
)
from caliburn.features.work_memory.models import MemoryMapEntry, MemorySourceWindow
from caliburn.features.work_memory.revision_service import read_fixed_revision
from caliburn.features.work_memory.revisions import (
    MemoryLayer,
    MemoryObjectRevision,
    MemoryRevisionNotFoundError,
    MemoryRevisionReference,
)


def batch_position(record: batch_persistence.MemoryBatchRecord) -> MemoryBatchPosition:
    return MemoryBatchPosition(
        record.job_file_id,
        record.execution_id,
        record.generation_id,
        record.stage_id,
        MemoryLayer(record.phase),
        record.current_position_id,
    )


def source_window(record: batch_persistence.MemoryBatchRecord) -> MemorySourceWindow:
    return MemorySourceWindow(
        record.job_file_id,
        record.through_source_id,
        record.covered_through_sequence,
        record.through_sequence,
    )


def snapshot_value(record: batch_persistence.MemorySnapshotRecord) -> MemorySnapshot:
    return MemorySnapshot(
        record.job_file_id,
        record.snapshot_id,
        record.position_id,
        record.through_source_id,
        record.covered_through_sequence,
    )


async def require_stage(
    session: AsyncSession, expected: MemoryBatchPosition, *, exact_position: bool = False
) -> batch_persistence.MemoryBatchRecord:
    record = await batch_persistence.read_batch(
        session, expected.job_file_id, expected.execution_id
    )
    if record is None or record.status != "open":
        raise MemoryCandidateStateError("No open Memory candidate in this execution")
    current = batch_position(record)
    if (
        current.generation_id != expected.generation_id
        or current.stage_id != expected.stage_id
        or current.phase != expected.phase
        or (exact_position and current.position_id != expected.position_id)
    ):
        raise MemoryCandidateStateError("The candidate stage or position was superseded")
    return record


async def read_members(
    session: AsyncSession, job_file_id: UUID, position_id: UUID
) -> dict[UUID, MemoryRevisionReference]:
    references = await position_persistence.read_position_members(session, job_file_id, position_id)
    if references is None:
        raise MemoryCandidateStateError("The fixed candidate position is unavailable")
    return {reference.object_id: reference for reference in references}


async def read_selected(
    session: AsyncSession,
    job_file_id: UUID,
    members: dict[UUID, MemoryRevisionReference],
    object_id: UUID,
) -> MemoryObjectRevision:
    reference = members.get(object_id)
    if reference is None:
        raise MemoryRevisionNotFoundError("The object is not selected at this position")
    return await read_fixed_revision(session, job_file_id=job_file_id, reference=reference)


async def read_candidate_map(
    session: AsyncSession, stage: MemoryBatchPosition, layer: MemoryLayer
) -> tuple[MemoryMapEntry, ...]:
    require_layer_read(stage.phase, layer)
    record = await require_stage(session, stage)
    return await position_persistence.read_position_map(
        session, stage.job_file_id, record.current_position_id, layer
    )


async def read_candidate_object(
    session: AsyncSession, stage: MemoryBatchPosition, layer: MemoryLayer, object_id: UUID
) -> MemoryCandidateObject:
    require_layer_read(stage.phase, layer)
    record = await require_stage(session, stage)
    # Capture one immutable position before resolving any reference. Never reread latest.
    members = await read_members(session, stage.job_file_id, record.current_position_id)
    revision = await read_selected(session, stage.job_file_id, members, object_id)
    if revision.layer != layer:
        raise MemoryRevisionNotFoundError("The object does not belong to the selected layer")
    return MemoryCandidateObject(
        revision.object_id,
        revision.revision_id,
        revision.layer,
        revision.content,
        revision.interview_references,
        frozenset(members[ref.object_id] for ref in revision.work_situation_references),
    )


async def read_snapshot(
    session: AsyncSession, job_file_id: UUID, snapshot_id: UUID
) -> MemorySnapshot:
    record = await batch_persistence.read_snapshot(session, job_file_id, snapshot_id)
    if record is None:
        raise MemoryRevisionNotFoundError("Published Memory snapshot not found in this job file")
    return snapshot_value(record)


async def read_latest_snapshot(session: AsyncSession, job_file_id: UUID) -> MemorySnapshot | None:
    head = await batch_persistence.read_head(session, job_file_id)
    return snapshot_value(head) if head is not None else None


async def read_snapshot_object(
    session: AsyncSession, job_file_id: UUID, snapshot_id: UUID, object_id: UUID
) -> MemoryObjectRevision:
    snapshot = await read_snapshot(session, job_file_id, snapshot_id)
    members = await read_members(session, job_file_id, snapshot.position_id)
    return await read_selected(session, job_file_id, members, object_id)


async def read_snapshot_map(
    session: AsyncSession, job_file_id: UUID, snapshot_id: UUID, layer: MemoryLayer
) -> tuple[MemoryMapEntry, ...]:
    snapshot = await read_snapshot(session, job_file_id, snapshot_id)
    return await position_persistence.read_position_map(
        session, job_file_id, snapshot.position_id, layer
    )

