def prepare_content_changes(
    current: MemoryContent,
    changes: tuple[MemoryFieldChange, ...],
    *,
    policy: BodyMatchPolicy = DEFAULT_BODY_MATCH_POLICY,
) -> MemoryContentChanges | None:
    validate_changes(changes)
    title = description = body = None
    for change in changes:
        if isinstance(change, MemoryTextChange):
            if change.field == "title":
                title = change.value
            else:
                description = change.value
        elif isinstance(change, MemoryBodyChange):
            body = apply_body_diff(current.body, change.diff, policy=policy)
    if title is None and description is None and body is None:
        return None
    return MemoryContentChanges(title, description, body)


def validate_changes(changes: tuple[MemoryFieldChange, ...]) -> None:
    if not 1 <= len(changes) <= 4:
        raise InvalidMemoryChangeError("One to four field changes are required")
    fields: list[str] = []
    for change in changes:
        if isinstance(change, MemoryTextChange):
            fields.append(change.field)
        elif isinstance(change, MemoryBodyChange):
            fields.append("body")
        elif isinstance(change, InterviewReferenceChange):
            fields.append("interview_references")
        else:
            fields.append("work_situation_references")
        if isinstance(change, InterviewReferenceChange | SituationReferenceChange):
            if not change.add and not change.remove:
                raise InvalidMemoryChangeError("A reference change cannot be empty")
    if len(fields) != len(set(fields)):
        raise InvalidMemoryChangeError("Each field may be changed only once")


def describe_body_change(before: str, after: str) -> str:
    """Standard contextual diff of actual text; not executable V4A or echoed model input."""
    lines = difflib.unified_diff(
        split_body_lines(before),
        split_body_lines(after),
        fromfile="body_before",
        tofile="body_after",
        n=3,
    )
    return "".join(
        line if line.endswith("\n") else line + "\n\\ No newline at end of file\n" for line in lines
    )

"""Internal Memory values and edit intent, independent of storage and model wire."""

from dataclasses import dataclass
from uuid import UUID


class InvalidMemoryChangeError(ValueError):
    """Memory content or an explicit change violates a domain invariant."""


class MemoryTitleConflictError(InvalidMemoryChangeError):
    """Another current object in the same layer owns the requested title."""


class MemoryReferenceNotFoundError(InvalidMemoryChangeError):
    """An explicitly removed source is not among this object's current bindings."""


class MemoryTargetNotFoundError(LookupError):
    """No exact title match exists in the caller's visible layer map."""


class MemoryMapInconsistencyError(RuntimeError):
    """The supplied layer map contains multiple entries for the selected title."""


class MemorySourceWindowError(ValueError):
    """A batch's required source window has invalid bounds or a non-employee endpoint."""


@dataclass(frozen=True, slots=True)
class MemorySourceWindow:
    """App-bound required interval (coverage, through], never a model parameter.

    Creation must resolve the triggering formal employee source. Restored values
    come from the original batch, not the latest history frontier.
    """

    job_file_id: UUID
    through_source_id: UUID
    covered_through_sequence: int
    through_sequence: int

    def __post_init__(self) -> None:
        if (
            type(self.covered_through_sequence) is not int
            or type(self.through_sequence) is not int
            or not 0 <= self.covered_through_sequence < self.through_sequence
        ):
            raise MemorySourceWindowError("A batch requires a nonempty, nonnegative source window")


def validate_memory_text(text: str) -> None:
    """Reject blank or unstorable content without changing the supplied string."""
    if not text.strip() or "\x00" in text:
        raise InvalidMemoryChangeError("Memory text must be nonblank without NUL")


@dataclass(frozen=True, slots=True)
class MemoryContent:
    """The three required content fields; references are separate identity sets."""

    title: str
    description: str
    body: str

    def __post_init__(self) -> None:
        for text in (self.title, self.description, self.body):
            validate_memory_text(text)


@dataclass(frozen=True, slots=True)
class MemoryContentChanges:
    """Internal intent: None is omitted; body is the result of a controlled patch.

    This is not a model-wire schema or a whole-body replacement tool.
    """

    title: str | None = None
    description: str | None = None
    body: str | None = None

    def __post_init__(self) -> None:
        supplied = tuple(
            text for text in (self.title, self.description, self.body) if text is not None
        )
        if not supplied:
            raise InvalidMemoryChangeError("Supply at least one content field")
        for text in supplied:
            validate_memory_text(text)


@dataclass(frozen=True, slots=True)
class ReferenceChanges:
    """Internal relationship changes after source choices resolve to stable IDs."""

    add: frozenset[UUID] = frozenset()
    remove: frozenset[UUID] = frozenset()

    def __post_init__(self) -> None:
        if not self.add and not self.remove:
            raise InvalidMemoryChangeError("Supply at least one reference to add or remove")
        if self.add & self.remove:
            raise InvalidMemoryChangeError("A reference cannot be both added and removed")


@dataclass(frozen=True, slots=True)
class MemoryMapEntry:
    """Internal title-to-identity projection for one caller-selected visible layer."""

    object_id: UUID
    title: str
    description: str

    def __post_init__(self) -> None:
        validate_memory_text(self.title)
        validate_memory_text(self.description)

"""Pin each read once so title selection, body and source navigation cannot mix positions."""

from uuid import UUID

from sqlalchemy.ext.asyncio import AsyncSession

from caliburn.features.work_memory import candidate_queries, position_persistence
from caliburn.features.work_memory.candidates import MemoryBatchPosition, require_layer_read
from caliburn.features.work_memory.models import MemoryMapEntry
from caliburn.features.work_memory.read_models import MemoryObjectReading, MemoryReadView
from caliburn.features.work_memory.revisions import MemoryLayer, MemoryRevisionNotFoundError


async def bind_candidate_view(
    session: AsyncSession, stage: MemoryBatchPosition, layer: MemoryLayer
) -> MemoryReadView:
    require_layer_read(stage.phase, layer)
    record = await candidate_queries.require_stage(session, stage)
    return MemoryReadView(
        stage.job_file_id, record.current_position_id, layer, record.through_sequence
    )


async def bind_published_view(
    session: AsyncSession, job_file_id: UUID, snapshot_id: UUID | None, layer: MemoryLayer
) -> MemoryReadView:
    if snapshot_id is None:
        # No snapshot at Turn start stays empty even if a publication happens later.
        return MemoryReadView(job_file_id, None, layer, 0)
    snapshot = await candidate_queries.read_snapshot(session, job_file_id, snapshot_id)
    return MemoryReadView(
        job_file_id, snapshot.position_id, layer, snapshot.covered_through_sequence
    )


async def read_map(session: AsyncSession, view: MemoryReadView) -> tuple[MemoryMapEntry, ...]:
    if view.position_id is None:
        return ()
    return await position_persistence.read_position_map(
        session, view.job_file_id, view.position_id, view.layer
    )


async def read_object(
    session: AsyncSession, view: MemoryReadView, object_id: UUID
) -> MemoryObjectReading:
    if view.position_id is None:
        raise MemoryRevisionNotFoundError("No Memory snapshot was selected for this Turn")
    members = await candidate_queries.read_members(session, view.job_file_id, view.position_id)
    revision = await candidate_queries.read_selected(session, view.job_file_id, members, object_id)
    if revision.layer != view.layer:
        raise MemoryRevisionNotFoundError("The object is not in the selected layer")
    situation_references: tuple[MemoryMapEntry, ...] = ()
    if revision.work_situation_references:
        # Candidate bindings follow identity; publication members already fix the chain.
        # Navigation needs source titles/descriptions, not every source's full body.
        situation_map = await position_persistence.read_position_map(
            session, view.job_file_id, view.position_id, MemoryLayer.WORK_SITUATION
        )
        source_ids = {reference.object_id for reference in revision.work_situation_references}
        situation_references = tuple(item for item in situation_map if item.object_id in source_ids)
        if len(situation_references) != len(source_ids):
            raise MemoryRevisionNotFoundError("A source binding is unavailable in the read view")
    return MemoryObjectReading(
        revision.content, revision.interview_references, situation_references
    )

"""Fixed Memory object revisions; candidate membership and publication are separate."""

from dataclasses import dataclass
from enum import StrEnum
from uuid import UUID

from caliburn.features.work_memory.models import InvalidMemoryChangeError, MemoryContent


class MemoryLayer(StrEnum):
    WORK_SITUATION = "work_situation"
    WORK_UNDERSTANDING = "work_understanding"


class MemoryRevisionNotFoundError(LookupError):
    """The requested fixed revision does not exist in this job file."""


@dataclass(frozen=True, slots=True, order=True)
class MemoryRevisionReference:
    object_id: UUID
    revision_id: UUID


@dataclass(frozen=True, slots=True)
class MemoryObjectRevision:
    object_id: UUID
    revision_id: UUID
    body_id: UUID
    layer: MemoryLayer
    content: MemoryContent
    interview_references: frozenset[UUID] = frozenset()
    work_situation_references: frozenset[MemoryRevisionReference] = frozenset()

    def __post_init__(self) -> None:
        if not isinstance(self.layer, MemoryLayer):
            raise InvalidMemoryChangeError("Select a defined Memory layer")
        if self.layer == MemoryLayer.WORK_SITUATION and self.work_situation_references:
            raise InvalidMemoryChangeError("Work situations may reference interviews only")
        if self.layer == MemoryLayer.WORK_UNDERSTANDING and self.interview_references:
            raise InvalidMemoryChangeError("Work understandings may reference situations only")
        if len({ref.object_id for ref in self.work_situation_references}) != len(
            self.work_situation_references
        ):
            raise InvalidMemoryChangeError("Select one fixed revision for each source situation")

"""Bind Memory source coverage through the formal interview owner's public queries."""

from uuid import UUID

from sqlalchemy.ext.asyncio import AsyncSession

from caliburn.features.interviews import queries as interviews
from caliburn.features.interviews.models import (
    InterviewMessage,
    InterviewReadScope,
    InterviewSpeaker,
    RecentInterviews,
)
from caliburn.features.work_memory.models import MemorySourceWindow, MemorySourceWindowError


async def bind_memory_source_window(
    session: AsyncSession,
    *,
    job_file_id: UUID,
    through_source_id: UUID,
    covered_through_sequence: int,
) -> MemorySourceWindow | None:
    """Resolve the original request's employee source; return None when already covered.

    Caller supplies K from the selected published snapshot and the exact source
    recorded with A's successful request. This query neither creates that intent
    nor persists a batch. Restore a started batch from its saved window instead.
    """
    if type(covered_through_sequence) is not int or covered_through_sequence < 0:
        raise MemorySourceWindowError("Coverage must be a nonnegative integer")
    # Latest frontier bounds validation only. F comes from the requested source,
    # not this max sequence, which also includes final replies and later turns.
    frontier = await interviews.read_history_frontier(session, job_file_id)
    scope = InterviewReadScope(job_file_id, frontier)
    (endpoint,) = await interviews.read_interview_sources(
        session, scope, source_ids=(through_source_id,)
    )
    if endpoint.speaker != InterviewSpeaker.EMPLOYEE:
        raise MemorySourceWindowError("A Memory request must end at a formal employee input")
    if covered_through_sequence:
        (covered,) = await interviews.read_interview_messages(
            session, scope, sequences=(covered_through_sequence,)
        )
        if covered.speaker != InterviewSpeaker.EMPLOYEE:
            raise MemorySourceWindowError("Published coverage must end at a formal employee input")
    if endpoint.interview_sequence <= covered_through_sequence:
        return None
    return MemorySourceWindow(
        job_file_id, through_source_id, covered_through_sequence, endpoint.interview_sequence
    )


async def read_required_interviews(
    session: AsyncSession, window: MemorySourceWindow
) -> RecentInterviews:
    """Read complete new sources using the batch's fixed bounds, without latest refresh."""
    return await interviews.read_recent_interviews(
        session,
        InterviewReadScope(window.job_file_id, window.through_sequence),
        covered_through_sequence=window.covered_through_sequence,
    )


async def read_reference_sources(
    session: AsyncSession, window: MemorySourceWindow, *, source_ids: frozenset[UUID]
) -> tuple[InterviewMessage, ...]:
    """Validate identity references against formal membership, file and fixed upper bound."""
    if not source_ids:
        return ()
    return tuple(
        await interviews.read_interview_sources(
            session,
            InterviewReadScope(window.job_file_id, window.through_sequence),
            source_ids=tuple(source_ids),
        )
    )

