class JdChangesTools:
    def __init__(
        self,
        reader: JdChangesWorkflow,
        binding: PublishedMemoryRead,
        *,
        manual_jd_start_revision_id: UUID,
        max_result_characters: int = 1_000_000,
    ) -> None:
        if max_result_characters < 1:
            raise ValueError("Tool result character limit must be positive")
        self.reader = reader
        self.binding = binding
        self.references = JdModelReferences(reader.sessions, binding.scope.job_file_id)
        self.manual_jd_start_revision_id = manual_jd_start_revision_id
        self.max_result_characters = max_result_characters

    @property
    def names(self) -> tuple[str, ...]:
        return ("read_jd_changes",)

    def definitions(self) -> list[FunctionToolParam]:
        return jd_changes_definitions()

    async def invoke(self, name: str, arguments: str) -> str:
        if name not in self.names:
            return "rejected: scope_not_allowed；使用 read_jd_changes。"
        try:
            query = parse_jd_changes(await resolve_jd_arguments(self.references, arguments))
        except JdReadTargetNotFoundError:
            return "rejected: target_not_found；重讀 read_jd，原樣帶回 App 提供的定位。"
        except ValidationError, ValueError:
            return (
                "rejected: invalid_arguments；選 manual 的合法 scope "
                "或 source 的 citation_ref，不帶版本。"
            )
        if isinstance(query, SourceChangeQuery):
            return await read_jd_source_changes(
                self.reader,
                self.binding,
                query.citation_ref,
                max_result_characters=self.max_result_characters,
            )
        try:
            result = await self.reader.read_manual(
                self.binding,
                manual_jd_start_revision_id=self.manual_jd_start_revision_id,
                scope=query.scope,
            )
        except ExecutionNotFoundError, ExecutionStateError:
            return "rejected: scope_not_allowed；目前 Turn 或固定人工差異範圍不允許讀取。"
        except CandidateStateError:
            return "rejected: target_stale；本 Turn 已無有效 JD 候選。"
        except JdReadTargetNotFoundError:
            return (
                "rejected: target_not_found；項目已不在目前 JD；已刪項目改用 all／area 讀人工差異。"
            )
        except HistoryConflictError, JdChangeHistoryUnavailableError:
            return (
                "rejected: source_not_available；固定人工比較基底或原操作不可取回，"
                "不回退成初始／空差異。"
            )
        aliases = await self.references.assign(
            {
                ref
                for snapshot in result.snapshots.values()
                for ref in (
                    *jd_read_refs(snapshot.work),
                    *(f"citation_{source.citation_id.hex}" for source in snapshot.sources),
                )
            }
        )
        output = project_jd_manual_changes(result, format_ref=lambda ref: aliases.get(ref, ref))
        if len(output) > self.max_result_characters:
            return (
                "rejected: read_limit_exceeded；完整人工差異超量，未截斷；"
                "請選合法 area／item／profile_field。"
            )
        return output


def project_jd_manual_changes(
    result: JdManualChanges, *, format_ref: Callable[[str], str] = str
) -> str:
    interval, snapshots, scope = result.interval, result.snapshots, result.scope
    before, after = snapshots[interval.base_revision_id], snapshots[interval.start_revision_id]
    operations: list[list[str]] = []
    for operation in interval.operations:
        old, new = snapshots[operation.before_revision_id], snapshots[operation.after_revision_id]
        delta = _manual_delta(old, new, scope, format_ref)
        if delta or _operation_touches(operation, old, new, scope):
            labels = tuple(format_ref(ref) for ref in _operation_labels(operation, old, new, scope))
            operations.append(
                [
                    *([f"受影響範圍：{', '.join(labels)}"] if labels else []),
                    *(delta or ["原操作已成立，但結果未改變（no-op）。"]),
                ]
            )
    lines = [
        "## JD 人工差異",
        f"比較：{'初始空 JD' if interval.initial_base else '上一成功 A 正式 JD'}"
        " → 本 Turn 起點正式 JD。",
        "只讀；未確認內容，也未解除來源待核對。本 Turn 候選修改不在此範圍。",
        f"本範圍人工操作：{len(operations)}",
    ]
    if not operations:
        lines.append("沒有人工操作。")
    else:
        lines.append("### 原操作的實際效果（歷史定位不保證仍存活；可編定位重讀 read_jd）")
        for index, delta in enumerate(operations, 1):
            lines.extend([f"#### 操作 {index}", *delta])
    net = _manual_delta(before, after, scope, format_ref)
    lines.extend(
        [
            "### 淨差異",
            *(net or ["淨差異：無；有操作不等於有淨改動。" if operations else "淨差異：無。"]),
        ]
    )
    return "\n".join(lines)


def _selected_items(
    snapshot: JdChangeSnapshot, scope: ManualChangeScope
) -> tuple[JdReadTarget, ...]:
    work = snapshot.work
    if isinstance(scope, AllManualChanges):
        return (*work.areas, *work.tasks, *work.capabilities, *work.collaborators, *work.conditions)
    if isinstance(scope, ProfileManualChanges) or (
        isinstance(scope, AreaManualChanges) and scope.view == ManualJdArea.PROFILE
    ):
        return ()
    if isinstance(scope, ItemManualChanges):
        try:
            return select_jd_items(work, "item", scope.read_ref)
        except JdReadTargetNotFoundError:
            return ()  # This historical endpoint lacks the currently validated identity.
    return select_jd_items(work, scope.view.value, None)


def _profile_fields(scope: ManualChangeScope) -> tuple[ProfileField, ...]:
    if isinstance(scope, ProfileManualChanges):
        return (scope.field,)
    if isinstance(scope, AllManualChanges) or (
        isinstance(scope, AreaManualChanges) and scope.view == ManualJdArea.PROFILE
    ):
        return tuple(ProfileField)
    return ()


def _snapshot_values(
    snapshot: JdChangeSnapshot, scope: ManualChangeScope
) -> dict[str, dict[str, JsonValue]]:
    values: dict[str, dict[str, JsonValue]] = {}
    for field in _profile_fields(scope):
        text = getattr(snapshot.profile, field.value)
        if text is not None:
            values[f"profile.{field.value}"] = {field.value: text}
    work = snapshot.work
    for item in _selected_items(snapshot, scope):
        value = project_jd_item(item, work, ())
        value.pop("supporting_sources")
        value.pop("read_ref")
        siblings: tuple[JdReadTarget, ...]
        match item:
            case ResponsibilityArea():
                siblings = work.areas
                value["task_read_refs"] = [
                    jd_read_ref(task) for task in work.tasks if task.area_id == item.area_id
                ]
            case WorkTask():
                siblings = tuple(task for task in work.tasks if task.area_id == item.area_id)
                value["area_read_ref"] = f"area_{item.area_id.hex}" if item.area_id else "未歸屬"
            case TaskDetail():
                task = next(task for task in work.tasks if item in task.details)
                siblings = tuple(detail for detail in task.details if detail.kind == item.kind)
                value["task_read_ref"] = jd_read_ref(task)
            case Capability():
                siblings = tuple(
                    capability for capability in work.capabilities if capability.kind == item.kind
                )
            case Collaborator():
                siblings = work.collaborators
            case JobCondition():
                siblings = tuple(
                    condition for condition in work.conditions if condition.kind == item.kind
                )
        value["position"] = siblings.index(item) + 1
        values[jd_read_ref(item)] = value
    return values


def _selected_sources(
    snapshot: JdChangeSnapshot, scope: ManualChangeScope
) -> dict[UUID, JdSourceReference]:
    targets = {
        *jd_read_source_targets(snapshot.work, _selected_items(snapshot, scope)),
        *(
            JdSourceTarget(SourceTargetKind.PROFILE_FIELD, field=field)
            for field in _profile_fields(scope)
        ),
    }
    return {
        reference.citation_id: reference
        for reference in snapshot.sources
        if reference.target in targets
    }


def _manual_delta(
    before: JdChangeSnapshot,
    after: JdChangeSnapshot,
    scope: ManualChangeScope,
    format_ref: Callable[[str], str],
) -> list[str]:
    old, new = _snapshot_values(before, scope), _snapshot_values(after, scope)
    lines = []
    for key in dict.fromkeys((*old, *new)):
        left, right = old.get(key), new.get(key)
        if left == right:
            continue
        effect = (
            "新增"
            if left is None
            else "刪除（歷史定位，不可編輯）"
            if right is None
            else "變更（文字／順序／歸屬／關聯）"
        )
        lines.append(f"{effect} · {format_ref(key)}")
        diff = describe_body_change(
            json.dumps(map_jd_reference_fields(left, format_ref), ensure_ascii=False, indent=2)
            if left is not None
            else "",
            json.dumps(map_jd_reference_fields(right, format_ref), ensure_ascii=False, indent=2)
            if right is not None
            else "",
        )
        fence = "`" * max(3, max(map(len, re.findall(r"`+", diff)), default=0) + 1)
        lines.extend([f"{fence}diff", diff, fence])
    old_sources, new_sources = _selected_sources(before, scope), _selected_sources(after, scope)
    for citation_id in dict.fromkeys((*old_sources, *new_sources)):
        left_source, right_source = old_sources.get(citation_id), new_sources.get(citation_id)
        if left_source is None:
            effect = "新增來源引用"
        elif right_source is None:
            effect = "移除來源引用"
        elif left_source.source != right_source.source:
            effect = "來源依據位置已改綁"
        elif left_source.needs_review != right_source.needs_review:
            effect = "來源改為待核對" if right_source.needs_review else "原操作已核對來源"
        else:
            continue
        selected = right_source or left_source
        assert selected is not None
        kind = (
            "interview"
            if isinstance(selected.source, InterviewSource)
            else selected.source.layer.value
        )
        target_label = _source_target_label(
            after if right_source else before, selected.target, format_ref
        )
        citation_ref = format_ref(f"citation_{citation_id.hex}")
        lines.append(f"{effect} · {target_label} · {citation_ref} · {kind}")
        if (
            left_source is not None
            and right_source is not None
            and left_source.source != right_source.source
            and left_source.needs_review != right_source.needs_review
        ):
            review = "待核對" if right_source.needs_review else "原操作已核對"
            lines.append(f"來源資格：{review} · {target_label} · {citation_ref}")
    return lines


def _source_target_label(
    snapshot: JdChangeSnapshot, target: JdSourceTarget, format_ref: Callable[[str], str]
) -> str:
    if target.kind == SourceTargetKind.PROFILE_FIELD:
        assert target.field is not None
        return f"profile.{target.field.value}"
    if target.kind == SourceTargetKind.TASK_CAPABILITY:
        capability = next(
            item for item in snapshot.work.capabilities if item.capability_id == target.item_id
        )
        assert target.task_id is not None
        return f"{format_ref(f'task_{target.task_id.hex}')} → {format_ref(jd_read_ref(capability))}"
    items = (
        *_selected_items(snapshot, AllManualChanges()),
        *(detail for task in snapshot.work.tasks for detail in task.details),
    )
    return next(
        format_ref(jd_read_ref(item))
        for item in items
        if jd_read_source_targets(snapshot.work, (item,))[0] == target
    )


def _operation_touches(
    operation: ManualJdOperation,
    before: JdChangeSnapshot,
    after: JdChangeSnapshot,
    scope: ManualChangeScope,
) -> bool:
    if isinstance(scope, AllManualChanges):
        return True
    return bool(_operation_labels(operation, before, after, scope))


def _operation_labels(
    operation: ManualJdOperation,
    before: JdChangeSnapshot,
    after: JdChangeSnapshot,
    scope: ManualChangeScope,
) -> tuple[str, ...]:
    fields = [
        f"profile.{field.value}"
        for field in _profile_fields(scope)
        if field in operation.profile_fields
    ]
    refs = {
        jd_read_ref(item)
        for snapshot in (before, after)
        for item in _selected_items(snapshot, scope)
    }
    return (
        *fields,
        *sorted(
            ref
            for ref in refs
            if any(ref.rsplit("_", 1)[-1] == item_id.hex for item_id in operation.item_ids)
        ),
    )


async def read_jd_source_changes(
    reader: JdChangesWorkflow,
    binding: PublishedMemoryRead,
    citation_ref: str,
    *,
    max_result_characters: int = 1_000_000,
) -> str:
    """Source branch only; registration must also implement the manual branch."""
    if max_result_characters < 1:
        raise ValueError("Tool result character limit must be positive")
    try:
        result = await reader.read_source(binding, citation_ref)
    except UnsupportedJdSourceKindError as error:
        return f"rejected: source_kind_not_supported；{error}"
    except ExecutionNotFoundError, ExecutionStateError, MemoryPermissionError, InterviewScopeError:
        return (
            "rejected: scope_not_allowed；目前執行或固定來源範圍不允許讀取；由 App 恢復合法範圍。"
        )
    except CandidateStateError:
        return "rejected: target_stale；本 Turn 已無有效 JD 候選；不可重送舊定位。"
    except JdReadTargetNotFoundError:
        return (
            "rejected: target_not_found；目前 JD 找不到引用；用 read_jd 局部讀取取得 citation_ref。"
        )
    except MemoryRevisionNotFoundError, MemoryCandidateStateError, InterviewSourceNotAvailableError:
        return (
            "rejected: source_not_available；固定來源或比較端點無法完整取回，未回傳假空差異；"
            "請由 App 核對保存資料，不推論來源已刪除。"
        )
    references = JdModelReferences(reader.sessions, binding.scope.job_file_id)
    canonical = f"citation_{result.reference.citation_id.hex}"
    assigned = await references.assign((canonical,))
    output = project_jd_source_changes(result, citation_ref=assigned[canonical])
    if len(output) > max_result_characters:
        return (
            "rejected: read_limit_exceeded；完整相關差異超過容量，未截斷或視為已讀；"
            "單筆來源已是最小合法範圍，交 App 處理。"
        )
    return output

"""The canonical two-query wire contains model choices, never revision coordinates."""

from caliburn.contracts.generated.tools import read_jd_changes_arguments as wire
from caliburn.features.job_description.models import ProfileField
from caliburn.workflows.jd_changes import (
    AllManualChanges,
    AreaManualChanges,
    ItemManualChanges,
    JdChangeQuery,
    ManualChangeQuery,
    ManualChangeScope,
    ManualJdArea,
    ProfileManualChanges,
    SourceChangeQuery,
)


def parse_jd_changes(arguments: str) -> JdChangeQuery:
    query = wire.ReadJdChangesArguments.model_validate_json(arguments).query
    if isinstance(query, wire.SourceQuery):
        if not query.citation_ref.strip():
            raise ValueError("Choose a citation_ref")
        return SourceChangeQuery(query.citation_ref)
    scope: ManualChangeScope
    if isinstance(query.scope, wire.AllScope):
        scope = AllManualChanges()
    elif isinstance(query.scope, wire.AreaScope):
        scope = AreaManualChanges(ManualJdArea(query.scope.view.value))
    elif isinstance(query.scope, wire.ItemScope):
        if not query.scope.read_ref.strip():
            raise ValueError("Choose a read_ref")
        scope = ItemManualChanges(query.scope.read_ref)
    else:
        scope = ProfileManualChanges(ProfileField(query.scope.field.value))
    return ManualChangeQuery(scope)

"""Complete local JD text and direct relationships, without expanding source chains."""

from pydantic import JsonValue

from caliburn.features.job_description.areas import ResponsibilityArea
from caliburn.features.job_description.capabilities import Capability, CapabilityKind
from caliburn.features.job_description.collaborators import Collaborator
from caliburn.features.job_description.conditions import JobCondition
from caliburn.features.job_description.models import JdProfile, ProfileField
from caliburn.features.job_description.navigation import (
    JdReadTarget,
    jd_read_ref,
    resolve_jd_read_ref,
)
from caliburn.features.job_description.sources import (
    InterviewSource,
    JdSourceTarget,
    SourceTargetKind,
)
from caliburn.features.job_description.tasks import DetailKind, TaskDetail, WorkTask
from caliburn.features.job_description.work_queries import JdWorkRevision
from caliburn.workflows.jd_reads import JdSourceReading


class InvalidJdReadSelectionError(ValueError):
    """The view and locator do not describe one of the supported read selections."""


def select_jd_items(
    work: JdWorkRevision, view: str, read_ref: str | None
) -> tuple[JdReadTarget, ...]:
    if view in {"item", "work_tasks"}:
        if read_ref is None:
            raise InvalidJdReadSelectionError("This view requires a JD read_ref")
        item = resolve_jd_read_ref(work, read_ref)
        if view == "item":
            return (item,)
        if not isinstance(item, ResponsibilityArea):
            raise InvalidJdReadSelectionError("work_tasks requires an area read_ref")
        return tuple(task for task in work.tasks if task.area_id == item.area_id)
    if read_ref is not None:
        raise InvalidJdReadSelectionError("This view requires a null read_ref")
    match view:
        case "responsibility_areas":
            return work.areas
        case "unassigned_work_tasks":
            return tuple(task for task in work.tasks if task.area_id is None)
        case "required_knowledge":
            return tuple(
                item for item in work.capabilities if item.kind == CapabilityKind.KNOWLEDGE
            )
        case "required_skills":
            return tuple(item for item in work.capabilities if item.kind == CapabilityKind.SKILL)
        case "main_collaborators":
            return work.collaborators
        case "job_wide_conditions":
            return work.conditions
        case _:
            raise InvalidJdReadSelectionError("Select a supported local JD view")


def jd_read_source_targets(
    work: JdWorkRevision, items: tuple[JdReadTarget, ...]
) -> tuple[JdSourceTarget, ...]:
    targets = []
    for item in items:
        targets.append(_item_source_target(item, work))
        if isinstance(item, WorkTask):
            targets.extend(_item_source_target(detail, work) for detail in item.details)
            targets.extend(
                JdSourceTarget(
                    SourceTargetKind.TASK_CAPABILITY, link.capability_id, task_id=link.task_id
                )
                for link in work.task_links
                if link.task_id == item.task_id
            )
        elif isinstance(item, Capability):
            targets.extend(
                JdSourceTarget(
                    SourceTargetKind.TASK_CAPABILITY, link.capability_id, task_id=link.task_id
                )
                for link in work.task_links
                if link.capability_id == item.capability_id
            )
    return tuple(dict.fromkeys(targets))


def project_jd_profile(
    profile: JdProfile, sources: tuple[JdSourceReading, ...]
) -> dict[str, JsonValue]:
    return {
        "job_title": profile.job_title,
        "organization_unit": profile.organization_unit,
        "reports_to": profile.reports_to,
        "purpose": profile.purpose,
        "supporting_sources": {
            field.value: _source_items(
                JdSourceTarget(SourceTargetKind.PROFILE_FIELD, field=field), sources
            )
            for field in ProfileField
        },
    }


def project_jd_item(
    item: JdReadTarget, work: JdWorkRevision, sources: tuple[JdSourceReading, ...]
) -> dict[str, JsonValue]:
    result: dict[str, JsonValue] = {"read_ref": jd_read_ref(item)}
    match item:
        case ResponsibilityArea():
            result.update(kind="responsibility_area", title=item.title, scope_text=item.scope_text)
        case WorkTask():
            result.update(
                kind="work_task",
                title=item.title,
                description=item.description,
                outcomes=[
                    _detail(detail, work, sources)
                    for detail in item.details
                    if detail.kind == DetailKind.OUTCOME
                ],
                requirements=[
                    _detail(detail, work, sources)
                    for detail in item.details
                    if detail.kind == DetailKind.REQUIREMENT
                ],
                required_knowledge=_task_capabilities(
                    item, work, CapabilityKind.KNOWLEDGE, sources
                ),
                required_skills=_task_capabilities(item, work, CapabilityKind.SKILL, sources),
            )
        case TaskDetail():
            result.update(kind=item.kind.value, text=item.text)
        case Capability():
            result.update(
                kind=item.kind.value,
                name=item.name,
                description=item.description,
                used_by_tasks=_capability_uses(item, work, sources),
            )
        case Collaborator():
            result.update(kind="collaborator", name=item.name, scope_text=item.scope_text)
        case JobCondition():
            result.update(kind="job_wide_condition", condition_kind=item.kind.value, text=item.text)
    result["supporting_sources"] = _source_items(_item_source_target(item, work), sources)
    return result


def _detail(
    item: TaskDetail, work: JdWorkRevision, sources: tuple[JdSourceReading, ...]
) -> dict[str, JsonValue]:
    return {
        "read_ref": jd_read_ref(item),
        "text": item.text,
        "supporting_sources": _source_items(_item_source_target(item, work), sources),
    }


def _task_capabilities(
    task: WorkTask, work: JdWorkRevision, kind: CapabilityKind, sources: tuple[JdSourceReading, ...]
) -> list[JsonValue]:
    capabilities = {item.capability_id: item for item in work.capabilities}
    result: list[JsonValue] = []
    for link in work.task_links:
        if link.task_id != task.task_id:
            continue
        item = capabilities[link.capability_id]
        if item.kind == kind:
            target = JdSourceTarget(
                SourceTargetKind.TASK_CAPABILITY, item.capability_id, task_id=task.task_id
            )
            result.append(
                {
                    "read_ref": jd_read_ref(item),
                    "name": item.name,
                    "supporting_sources": _source_items(target, sources),
                }
            )
    return result


def _capability_uses(
    item: Capability, work: JdWorkRevision, sources: tuple[JdSourceReading, ...]
) -> list[JsonValue]:
    task_ids = {
        link.task_id for link in work.task_links if link.capability_id == item.capability_id
    }
    result: list[JsonValue] = []
    for task in work.tasks:
        if task.task_id in task_ids:
            target = JdSourceTarget(
                SourceTargetKind.TASK_CAPABILITY, item.capability_id, task_id=task.task_id
            )
            result.append(
                {
                    "read_ref": jd_read_ref(task),
                    "title": task.title,
                    "supporting_sources": _source_items(target, sources),
                }
            )
    return result


def _item_source_target(item: JdReadTarget, work: JdWorkRevision) -> JdSourceTarget:
    match item:
        case ResponsibilityArea():
            return JdSourceTarget(SourceTargetKind.AREA, item.area_id)
        case WorkTask():
            return JdSourceTarget(SourceTargetKind.TASK, item.task_id)
        case TaskDetail():
            for task in work.tasks:
                if any(detail.detail_id == item.detail_id for detail in task.details):
                    return JdSourceTarget(
                        SourceTargetKind.DETAIL, item.detail_id, task_id=task.task_id
                    )
            raise InvalidJdReadSelectionError("The detail is not in this JD revision")
        case Capability():
            return JdSourceTarget(SourceTargetKind.CAPABILITY, item.capability_id)
        case Collaborator():
            return JdSourceTarget(SourceTargetKind.COLLABORATOR, item.collaborator_id)
        case JobCondition():
            return JdSourceTarget(SourceTargetKind.CONDITION, item.condition_id)


def _source_items(target: JdSourceTarget, sources: tuple[JdSourceReading, ...]) -> list[JsonValue]:
    result: list[JsonValue] = []
    for reading in sources:
        reference = reading.reference
        if reference.target != target:
            continue
        item: dict[str, JsonValue] = {"citation_ref": f"citation_{reference.citation_id.hex}"}
        if isinstance(reference.source, InterviewSource):
            if reading.interview_sequence is None:
                item["kind"] = "current_input"
            else:
                item.update(kind="interview", interview_sequence=reading.interview_sequence)
        else:
            item["kind"] = reference.source.layer.value
            if reading.target_title is not None:
                item["target_title"] = reading.target_title
            if reading.historical_title is not None:
                item["historical_title"] = reading.historical_title
        if reference.needs_review or reading.needs_recheck:
            item["needs_recheck"] = True
        result.append(item)
    return result

"""Generated create_jd_item variants translate to existing domain create values."""

from caliburn.contracts.generated.tools import create_jd_item_arguments as wire
from caliburn.features.job_description.areas import CreateArea
from caliburn.features.job_description.capabilities import CapabilityKind, CreateCapability
from caliburn.features.job_description.collaborators import CreateCollaborator
from caliburn.features.job_description.conditions import ConditionKind, CreateCondition
from caliburn.features.job_description.sources import MemorySourceLayer
from caliburn.workflows.jd_item_creation import CreateItemInput, ItemCreation
from caliburn.workflows.jd_sources import (
    CurrentInputSourceSelection,
    InterviewSourceSelection,
    JdSourceSelection,
    MemorySourceSelection,
)


def parse_item_creation(arguments: str) -> CreateItemInput:
    item = wire.CreateJdItemArguments.model_validate_json(arguments).item
    creation: ItemCreation
    if isinstance(item, wire.ResponsibilityAreaItem):
        creation = CreateArea(item.title, item.scope_text)
    elif isinstance(item, wire.CapabilityItem):
        creation = CreateCapability(CapabilityKind(item.kind.value), item.name, item.description)
    elif isinstance(item, wire.CollaboratorItem):
        creation = CreateCollaborator(item.name, item.scope_text)
    else:
        creation = CreateCondition(ConditionKind(item.condition_kind.value), item.text)
    return CreateItemInput(
        creation, tuple(_source_selection(source.root) for source in item.supporting_sources)
    )


def _source_selection(
    source: wire.CurrentInputSource | wire.InterviewSource | wire.MemorySource,
) -> JdSourceSelection:
    if isinstance(source, wire.CurrentInputSource):
