"""One model profile intent binds evidence once and applies all effects in one transaction."""

from dataclasses import dataclass
from uuid import UUID, uuid5

from sqlalchemy.ext.asyncio import AsyncSession, async_sessionmaker

from caliburn.features.executions import service as executions
from caliburn.features.executions.models import (
    ExecutionStateError,
    ExecutionStatus,
    ExecutionWriter,
)
from caliburn.features.job_description import (
    candidate_service,
    revision_editing,
    source_persistence,
)
from caliburn.features.job_description.candidates import JdCandidateScope
from caliburn.features.job_description.models import ProfileChange, ProfileField, ReviseJdProfile
from caliburn.features.job_description.sources import (
    AddJdSource,
    AlignJdSource,
    InvalidJdSourceError,
    JdSourceChange,
    JdSourceTarget,
    RemoveJdSource,
    ReviseJdSources,
    SourceTargetKind,
)
from caliburn.features.job_files import service as job_files
from caliburn.workflows.jd_candidates import apply_candidate_edit
from caliburn.workflows.jd_sources import (
    JdSourceSelection,
    resolve_aligned_jd_source,
    resolve_jd_source,
)
from caliburn.workflows.memory_reads import PublishedMemoryRead


@dataclass(frozen=True, slots=True)
class AddProfileSource:
    field: ProfileField
    source: JdSourceSelection


@dataclass(frozen=True, slots=True)
class RemoveProfileSource:
    field: ProfileField
    citation_ref: str


@dataclass(frozen=True, slots=True)
class AlignProfileSource:
    field: ProfileField
    citation_ref: str


type ProfileSourceIntent = AddProfileSource | RemoveProfileSource | AlignProfileSource


@dataclass(frozen=True, slots=True)
class BoundProfileSources:
    field: ProfileField
    changes: tuple[JdSourceChange, ...]


@dataclass(frozen=True, slots=True)
class PreparedProfileWrite:
    command_id: UUID
    candidate: JdCandidateScope
    expected_revision_id: UUID
    changes: tuple[ProfileChange, ...]
    sources: tuple[BoundProfileSources, ...]


class JdProfileWriteWorkflow:
    def __init__(self, sessions: async_sessionmaker[AsyncSession]) -> None:
        self.sessions = sessions

    async def prepare(
        self,
        binding: PublishedMemoryRead,
        *,
        command_id: UUID,
        changes: tuple[ProfileChange, ...],
        sources: tuple[ProfileSourceIntent, ...],
    ) -> PreparedProfileWrite:
        if not changes and not sources:
            raise InvalidJdSourceError("Choose at least one profile change")
        async with self.sessions() as session:
            execution = await executions.read_execution(session, binding.scope)
            if execution.status != ExecutionStatus.ACTIVE:
                raise ExecutionStateError("This Turn cannot prepare JD changes")
            preview = await candidate_service.read_preview(
                session, binding.scope.job_file_id, binding.scope.execution_id
            )
            position = preview.position
            if changes:
                ReviseJdProfile(command_id, position.revision_id, changes)
            references = await source_persistence.read_source_references(
                session, binding.scope.job_file_id, position.revision_id
            )
            grouped: dict[ProfileField, list[JdSourceChange]] = {}
            for intention in sources:
                target = JdSourceTarget(SourceTargetKind.PROFILE_FIELD, field=intention.field)
                if isinstance(intention, AddProfileSource):
                    source = await resolve_jd_source(session, binding, intention.source)
                    change: JdSourceChange = AddJdSource(source)
                else:
                    reference = next(
                        (
                            ref
                            for ref in references
                            if (
                                ref.target == target
                                and f"citation_{ref.citation_id.hex}" == intention.citation_ref
                            )
                        ),
                        None,
                    )
                    if reference is None:
                        raise InvalidJdSourceError(
                            "The citation does not belong to this profile field"
                        )
                    if isinstance(intention, RemoveProfileSource):
                        change = RemoveJdSource(reference.citation_id)
                    else:
                        change = AlignJdSource(
                            reference.citation_id,
                            await resolve_aligned_jd_source(session, binding, reference.source),
                        )
                grouped.setdefault(intention.field, []).append(change)
            bound = tuple(
                BoundProfileSources(field, tuple(values)) for field, values in grouped.items()
            )
            for group in bound:
                ReviseJdSources(
                    command_id,
                    position.revision_id,
                    JdSourceTarget(SourceTargetKind.PROFILE_FIELD, field=group.field),
                    group.changes,
                )
            return PreparedProfileWrite(
                command_id, position.scope, position.revision_id, changes, bound
            )

    async def execute(self, writer: ExecutionWriter, prepared: PreparedProfileWrite) -> str:
        if writer.scope.execution_id != prepared.candidate.execution_id:
            raise ExecutionStateError("This prepared edit belongs to a different Turn")
        async with self.sessions.begin() as session:
            await job_files.lock_job_file(session, writer.scope.job_file_id)
            await executions.lock_active_writer(session, writer)
            await revision_editing.require_open_candidate(
                session, writer.scope.job_file_id, prepared.candidate
            )
            revision = prepared.expected_revision_id
            if prepared.changes:
                revision = await apply_candidate_edit(
                    session,
                    writer.scope.job_file_id,
                    prepared.candidate,
                    ReviseJdProfile(
                        uuid5(prepared.command_id, "profile_text"), revision, prepared.changes
                    ),
                )
            for group in prepared.sources:
                revision = await apply_candidate_edit(
                    session,
                    writer.scope.job_file_id,
                    prepared.candidate,
                    ReviseJdSources(
                        uuid5(prepared.command_id, f"profile_source:{group.field}"),
                        revision,
                        JdSourceTarget(SourceTargetKind.PROFILE_FIELD, field=group.field),
                        group.changes,
                    ),
                )
            if revision == prepared.expected_revision_id:
                return "unchanged"
            if not prepared.changes and all(
                isinstance(change, AlignJdSource)
                for group in prepared.sources
                for change in group.changes
            ):
                return "aligned"
            return "updated"

apps/api/src/caliburn/workflows/jd_reads:
"""Read one A candidate and its direct evidence through the original data owners."""

from dataclasses import dataclass

from sqlalchemy.ext.asyncio import AsyncSession, async_sessionmaker

from caliburn.features.executions import service as executions
from caliburn.features.executions.models import ExecutionStateError, ExecutionStatus
from caliburn.features.interviews import queries as interviews
from caliburn.features.interviews.models import InterviewInputNotFoundError, InterviewReadScope
from caliburn.features.job_description import source_persistence
from caliburn.features.job_description.candidate_service import JdCandidatePreview
from caliburn.features.job_description.navigation import JdReadTargetNotFoundError
from caliburn.features.job_description.sources import (
    InterviewSource,
    JdSourceReference,
    JdSourceTarget,
    MemorySource,
)
from caliburn.workflows.jd_candidates import JdCandidateWorkflow
from caliburn.workflows.jd_source_queries import read_memory_source_titles
from caliburn.workflows.memory_reads import PublishedMemoryRead


@dataclass(frozen=True, slots=True)
class JdSourceReading:
    """Qualified read hints only; no source bodies or replacement identities."""

    reference: JdSourceReference
    interview_sequence: int | None = None
    target_title: str | None = None
    historical_title: str | None = None
    needs_recheck: bool = False


class JdReadWorkflow:
    def __init__(self, sessions: async_sessionmaker[AsyncSession]) -> None:
        self.sessions = sessions

    async def read_candidate(self, binding: PublishedMemoryRead) -> JdCandidatePreview:
        return await JdCandidateWorkflow(self.sessions).read(binding.scope)

    async def read_sources(
        self,
        binding: PublishedMemoryRead,
        candidate: JdCandidatePreview,
        targets: tuple[JdSourceTarget, ...],
    ) -> tuple[JdSourceReading, ...]:
        """Resolve only requested evidence from the candidate revision already read.

        Concurrent candidate edits cannot switch these references to a later head.
        Missing fixed source data is an error, not an empty evidence list or deletion.
        """
        if candidate.position.scope.execution_id != binding.scope.execution_id:
            raise ExecutionStateError("The candidate belongs to a different Turn")
        async with self.sessions() as session:
            execution = await executions.read_execution(session, binding.scope)
            if execution.status not in (ExecutionStatus.ACTIVE, ExecutionStatus.PAUSED):
                raise ExecutionStateError("This Turn no longer has a readable JD candidate")
            references = await source_persistence.read_source_references(
                session, binding.scope.job_file_id, candidate.position.revision_id
            )
            selected = tuple(reference for reference in references if reference.target in targets)
            sequences = await _interview_sequences(session, binding, selected)
            memory_titles: dict[MemorySource, tuple[str | None, str | None, bool]] = {}
            readings = []
            for reference in selected:
                source = reference.source
                if isinstance(source, InterviewSource):
                    readings.append(
                        JdSourceReading(reference, interview_sequence=sequences[source])
                    )
                    continue
                if source not in memory_titles:
                    memory_titles[source] = await read_memory_source_titles(
                        session,
                        job_file_id=binding.scope.job_file_id,
                        source=source,
                        snapshot_id=binding.snapshot_id,
                        interview_through_sequence=binding.interview_through_sequence,
                    )
                title, historical_title, changed = memory_titles[source]
                readings.append(
                    JdSourceReading(
                        reference,
                        target_title=title,
                        historical_title=historical_title,
                        needs_recheck=reference.needs_review or changed,
                    )
                )
            return tuple(readings)


async def _interview_sequences(
    session: AsyncSession, binding: PublishedMemoryRead, references: tuple[JdSourceReference, ...]
) -> dict[InterviewSource, int | None]:
    selected = tuple(
        reference.source
        for reference in references
        if isinstance(reference.source, InterviewSource)
    )
    if not selected:
        return {}
    try:
        original = await interviews.read_execution_input(
            session, job_file_id=binding.scope.job_file_id, execution_id=binding.scope.execution_id
        )
    except InterviewInputNotFoundError:
        # Formal references do not require this Turn to have a pending input.
        original = None
    current_id = original.source_id if original is not None else None
    formal_ids = tuple(source.source_id for source in selected if source.source_id != current_id)
    messages = (
        await interviews.read_interview_sources(
            session,
            InterviewReadScope(binding.scope.job_file_id, binding.interview_through_sequence),
            source_ids=formal_ids,
        )
        if formal_ids
        else []
    )
    result: dict[InterviewSource, int | None] = {
        InterviewSource(message.source_id): message.interview_sequence for message in messages
    }
    if current_id is not None:
        result[InterviewSource(current_id)] = None
    return result


def resolve_jd_citation_ref(
    references: tuple[JdSourceReference, ...], citation_ref: str
) -> JdSourceReference:
    """The caller supplies the scoped source tuple; an echoed ref grants no extra scope."""
    for reference in references:
        if citation_ref == f"citation_{reference.citation_id.hex}":
            return reference
    raise JdReadTargetNotFoundError("No such citation in the scoped JD references")

apps/api/src/caliburn/workflows/jd_sourc:
"""Qualify JD evidence through its source owner within A's fixed visible scope."""

from dataclasses import dataclass

from sqlalchemy.ext.asyncio import AsyncSession

from caliburn.features.executions import service as executions
from caliburn.features.executions.models import ExecutionStateError, ExecutionStatus
from caliburn.features.interviews import queries as interviews
from caliburn.features.interviews.models import InterviewReadScope
from caliburn.features.job_description.sources import (
    InterviewSource,
    InvalidJdSourceError,
    JdSource,
    MemorySource,
    MemorySourceLayer,
)
from caliburn.features.work_memory import candidate_queries as memory
from caliburn.features.work_memory.changes import resolve_title
from caliburn.features.work_memory.revisions import MemoryLayer
from caliburn.workflows.memory_reads import PublishedMemoryRead


@dataclass(frozen=True, slots=True)
class InterviewSourceSelection:
    interview_sequence: int


@dataclass(frozen=True, slots=True)
class CurrentInputSourceSelection:
    pass


@dataclass(frozen=True, slots=True)
class MemorySourceSelection:
    layer: MemorySourceLayer
    target_title: str


type JdSourceSelection = (
    InterviewSourceSelection | CurrentInputSourceSelection | MemorySourceSelection
)


async def resolve_jd_source(
    session: AsyncSession, binding: PublishedMemoryRead, selection: JdSourceSelection
) -> JdSource:
    """Resolve model choices to real immutable identities; do not accept model versions/IDs."""
    await _require_active(session, binding)
    job_file_id = binding.scope.job_file_id
    if isinstance(selection, CurrentInputSourceSelection):
        original = await interviews.read_execution_input(
            session, job_file_id=job_file_id, execution_id=binding.scope.execution_id
        )
        return InterviewSource(original.source_id)
    if isinstance(selection, InterviewSourceSelection):
        messages = await interviews.read_interview_messages(
            session,
            InterviewReadScope(job_file_id, binding.interview_through_sequence),
            sequences=(selection.interview_sequence,),
        )
        return InterviewSource(messages[0].source_id)
    await _require_snapshot(session, binding)
    assert binding.snapshot_id is not None
    entries = await memory.read_snapshot_map(
        session, job_file_id, binding.snapshot_id, MemoryLayer(selection.layer.value)
    )
    object_id = resolve_title(entries, selection.target_title)
    revision = await memory.read_snapshot_object(
        session, job_file_id, binding.snapshot_id, object_id
    )
    return MemorySource(selection.layer, binding.snapshot_id, object_id, revision.revision_id)


async def resolve_aligned_jd_source(
    session: AsyncSession, binding: PublishedMemoryRead, original: JdSource
) -> JdSource:
    """Align by the existing citation identity, never by a reused historical title."""
    await _require_active(session, binding)
    job_file_id = binding.scope.job_file_id
    if isinstance(original, InterviewSource):
        current = await interviews.read_execution_input(
            session, job_file_id=job_file_id, execution_id=binding.scope.execution_id
        )
        if original.source_id != current.source_id:
            await interviews.read_interview_sources(
                session,
                InterviewReadScope(job_file_id, binding.interview_through_sequence),
                source_ids=(original.source_id,),
            )
        return original
    await _require_snapshot(session, binding)
    assert binding.snapshot_id is not None
    selected = await memory.read_snapshot_object(
        session, job_file_id, binding.snapshot_id, original.object_id
    )
    if selected.layer.value != original.layer.value:
        raise InvalidJdSourceError("The original source is not in the selected layer")
    return MemorySource(
        original.layer, binding.snapshot_id, original.object_id, selected.revision_id
    )


async def _require_active(session: AsyncSession, binding: PublishedMemoryRead) -> None:
    if (await executions.read_execution(session, binding.scope)).status != ExecutionStatus.ACTIVE:
        raise ExecutionStateError("This Turn cannot qualify new JD evidence")


async def _require_snapshot(session: AsyncSession, binding: PublishedMemoryRead) -> None:
    if binding.snapshot_id is None:
        raise InvalidJdSourceError("No Memory snapshot was selected for this Turn")
    snapshot = await memory.read_snapshot(session, binding.scope.job_file_id, binding.snapshot_id)
    if snapshot.covered_through_sequence > binding.interview_through_sequence:
        raise InvalidJdSourceError("The Memory source exceeds this Turn's visible interviews")

apps/api/src/caliburn/workflows/memory_r:
"""App-bound Memory reads shared by the consultant and both analysis roles."""

from dataclasses import dataclass
from uuid import UUID

from sqlalchemy.ext.asyncio import AsyncSession, async_sessionmaker

from caliburn.features.executions import service as executions
from caliburn.features.executions.models import (
    ExecutionKind,
    ExecutionScope,
    ExecutionStateError,
    ExecutionStatus,
)
from caliburn.features.interviews import queries as interviews
from caliburn.features.interviews.models import InterviewMessage, InterviewReadScope
from caliburn.features.work_memory import candidate_queries, read_queries
from caliburn.features.work_memory.candidates import MemoryBatchPosition, MemoryPermissionError
from caliburn.features.work_memory.changes import resolve_title
from caliburn.features.work_memory.models import MemoryMapEntry
from caliburn.features.work_memory.read_models import MemoryObjectDetails, MemoryReadView
from caliburn.features.work_memory.revisions import MemoryLayer


@dataclass(frozen=True, slots=True)
class PublishedMemoryRead:
    """Restored from A's original Turn binding, never recalculated from latest."""

    scope: ExecutionScope
    snapshot_id: UUID | None
    interview_through_sequence: int

    def __post_init__(self) -> None:
        if self.scope.kind != ExecutionKind.CONSULTANT_TURN:
            raise MemoryPermissionError("Published model reads require a consultant Turn")
        InterviewReadScope(self.scope.job_file_id, self.interview_through_sequence)


@dataclass(frozen=True, slots=True)
class CandidateMemoryRead:
    """Stage stays fixed; each call sees that stage's latest valid candidate position."""

    scope: ExecutionScope
    stage: MemoryBatchPosition

    def __post_init__(self) -> None:
        if self.scope.kind != ExecutionKind.MEMORY_BATCH or (
            self.scope.job_file_id,
            self.scope.execution_id,
        ) != (self.stage.job_file_id, self.stage.execution_id):
            raise MemoryPermissionError("Candidate reads require the owning Memory batch")


type MemoryReadBinding = PublishedMemoryRead | CandidateMemoryRead


class MemoryReadWorkflow:
    def __init__(self, sessions: async_sessionmaker[AsyncSession]) -> None:
        self.sessions = sessions

    async def read_map(
        self, binding: MemoryReadBinding, layer: MemoryLayer
    ) -> tuple[MemoryMapEntry, ...]:
        async with self.sessions() as session:
            view = await _bind_view(session, binding, layer)
            return await read_queries.read_map(session, view)

    async def read_object(
        self, binding: MemoryReadBinding, layer: MemoryLayer, target_title: str
    ) -> MemoryObjectDetails:
        async with self.sessions() as session:
            view = await _bind_view(session, binding, layer)
            entries = await read_queries.read_map(session, view)
            object_id = resolve_title(entries, target_title)
            reading = await read_queries.read_object(session, view, object_id)
            messages = (
                await interviews.read_interview_sources(
                    session,
                    InterviewReadScope(view.job_file_id, view.through_sequence),
                    source_ids=tuple(reading.interview_source_ids),
                )
                if reading.interview_source_ids
                else []
            )
            return MemoryObjectDetails(
                reading.content,
                tuple(message.interview_sequence for message in messages),
                reading.work_situation_references,
            )

    async def read_interview_messages(
        self, binding: MemoryReadBinding, sequences: tuple[int, ...]
    ) -> tuple[InterviewMessage, ...]:
        async with self.sessions() as session:
            scope = await _interview_scope(session, binding)
            return tuple(
                await interviews.read_interview_messages(session, scope, sequences=sequences)
            )

    async def read_interview_range(
        self, binding: MemoryReadBinding, *, start_sequence: int, end_sequence: int
    ) -> tuple[InterviewMessage, ...]:
        async with self.sessions() as session:
            scope = await _interview_scope(session, binding)
            return tuple(
                await interviews.read_interview_range(
                    session, scope, start_sequence=start_sequence, end_sequence=end_sequence
                )
            )


async def _require_active(session: AsyncSession, scope: ExecutionScope) -> None:
    if (await executions.read_execution(session, scope)).status != ExecutionStatus.ACTIVE:
        raise ExecutionStateError("This execution cannot make new model tool reads")


async def _bind_view(
    session: AsyncSession, binding: MemoryReadBinding, layer: MemoryLayer
) -> MemoryReadView:
    await _require_active(session, binding.scope)
    if isinstance(binding, CandidateMemoryRead):
        return await read_queries.bind_candidate_view(session, binding.stage, layer)
    view = await read_queries.bind_published_view(
        session, binding.scope.job_file_id, binding.snapshot_id, layer
    )
    if view.through_sequence > binding.interview_through_sequence:
        raise MemoryPermissionError("Memory coverage exceeds this Turn's fixed interview scope")
    return view


async def _interview_scope(session: AsyncSession, binding: MemoryReadBinding) -> InterviewReadScope:
    await _require_active(session, binding.scope)
    if isinstance(binding, CandidateMemoryRead):
        record = await candidate_queries.require_stage(session, binding.stage)
        return InterviewReadScope(binding.scope.job_file_id, record.through_sequence)
    return InterviewReadScope(binding.scope.job_file_id, binding.interview_through_sequence)

apps/api/src/caliburn/workflows/memory_w:
"""Resolve a new model intent once; execution reuses the original bound candidate command."""

import asyncio
from typing import Literal
from uuid import UUID, uuid4

from sqlalchemy.ext.asyncio import AsyncSession, async_sessionmaker

from caliburn.features.executions import service as executions
from caliburn.features.executions.models import ExecutionStateError, ExecutionStatus
from caliburn.features.interviews import queries as interviews
from caliburn.features.interviews.models import InterviewReadScope
from caliburn.features.work_memory import candidate_queries, read_queries
from caliburn.features.work_memory.body_edits import DEFAULT_BODY_MATCH_POLICY
from caliburn.features.work_memory.body_matching import BodyEditError, BodyMatchPolicy
from caliburn.features.work_memory.candidates import (
    CreateMemoryObject,
    DeleteMemoryObject,
    MemoryPermissionError,
    ReviseMemoryObject,
    require_layer_write,
)
from caliburn.features.work_memory.changes import (
    apply_content_changes,
    apply_reference_changes,
    require_unique_title,
    resolve_title,
)
from caliburn.features.work_memory.edit_intents import (
    CreateMemoryIntent,
    DeleteMemoryIntent,
    InterviewReferenceChange,
    InterviewSourceSelection,
    MemoryWriteIntent,
    SituationReferenceChange,
    SituationSourceSelection,
)
from caliburn.features.work_memory.edit_preparation import (
    MemoryStatusPreview,
    MemoryUpdatePreview,
    PreparedMemoryEdit,
    describe_body_change,
    prepare_content_changes,
    validate_changes,
)
from caliburn.features.work_memory.models import MemoryContent, ReferenceChanges
from caliburn.features.work_memory.read_models import MemoryReadView
from caliburn.features.work_memory.revisions import MemoryLayer
from caliburn.workflows.memory_reads import CandidateMemoryRead


class MemoryWritePreparation:
    """Reads and computes only; no locks across CPU work and no business writes."""

    def __init__(
        self,
        sessions: async_sessionmaker[AsyncSession],
        *,
        body_policy: BodyMatchPolicy = DEFAULT_BODY_MATCH_POLICY,
    ) -> None:
        self.sessions = sessions
        self.body_policy = body_policy

    async def prepare(
        self,
        binding: CandidateMemoryRead,
        *,
        command_id: UUID,
        layer: MemoryLayer,
        intent: MemoryWriteIntent,
    ) -> PreparedMemoryEdit:
        require_layer_write(binding.stage.phase, layer)
        async with self.sessions() as session:
            if (
                await executions.read_execution(session, binding.scope)
            ).status != ExecutionStatus.ACTIVE:
                raise ExecutionStateError("This execution cannot prepare a new Memory write")
            record = await candidate_queries.require_stage(session, binding.stage)
            position = candidate_queries.batch_position(record)
            view = MemoryReadView(
                position.job_file_id, position.position_id, layer, record.through_sequence
            )
            entries = await read_queries.read_map(session, view)
            if isinstance(intent, CreateMemoryIntent):
                _require_source_layer(layer, intent.sources)
                selected = await _resolve_sources(session, view, intent.sources)
                _require_body_capacity(intent.content.body, self.body_policy)
                require_unique_title(uuid4(), intent.content, entries)
                return PreparedMemoryEdit(
                    CreateMemoryObject(
                        command_id, position, layer, intent.content, frozenset(selected)
                    ),
                    MemoryStatusPreview("created"),
                )
            object_id = resolve_title(entries, intent.target_title)
            if isinstance(intent, DeleteMemoryIntent):
                return PreparedMemoryEdit(
                    DeleteMemoryObject(command_id, position, layer, object_id),
                    MemoryStatusPreview("deleted"),
                )
            validate_changes(intent.changes)
            before = await read_queries.read_object(session, view, object_id)
            current_sources = (
                before.interview_source_ids
                if layer == MemoryLayer.WORK_SITUATION
                else frozenset(item.object_id for item in before.work_situation_references)
            )
            reference_change: ReferenceChanges | None = None
            added: dict[UUID, int | str] = {}
            removed: dict[UUID, int | str] = {}
            additions: InterviewSourceSelection | SituationSourceSelection
            removals: InterviewSourceSelection | SituationSourceSelection
            for change in intent.changes:
                if isinstance(change, InterviewReferenceChange):
                    additions = InterviewSourceSelection(change.add)
                    removals = InterviewSourceSelection(change.remove)
                elif isinstance(change, SituationReferenceChange):
                    additions = SituationSourceSelection(change.add)
                    removals = SituationSourceSelection(change.remove)
                else:
                    continue
                _require_source_layer(layer, additions)
                added = await _resolve_sources(session, view, additions)
                removed = await _resolve_sources(session, view, removals)
                reference_change = ReferenceChanges(frozenset(added), frozenset(removed))
            next_sources = (
                current_sources
                if reference_change is None
                else apply_reference_changes(current_sources, reference_change, frozenset(added))
            )
        # Patch search can be expensive. Release the read session first and keep the
        # event loop responsive; apply later uses this exact position, never latest.
        content_changes = await asyncio.to_thread(
            prepare_content_changes, before.content, intent.changes, policy=self.body_policy
        )
        after = (
            before.content
            if content_changes is None
            else apply_content_changes(before.content, content_changes)
        )
        require_unique_title(object_id, after, entries)
        preview = await asyncio.to_thread(
            _update_preview,
            layer,
            before.content,
            after,
            tuple(added[key] for key in added if key in next_sources - current_sources),
            tuple(removed[key] for key in removed if key in current_sources - next_sources),
        )
        return PreparedMemoryEdit(
            ReviseMemoryObject(
                command_id, position, layer, object_id, content_changes, reference_change
            ),
            preview,
        )


def _require_source_layer(
    layer: MemoryLayer, selection: InterviewSourceSelection | SituationSourceSelection
) -> None:
    if (layer == MemoryLayer.WORK_SITUATION) != isinstance(selection, InterviewSourceSelection):
        raise MemoryPermissionError("The source selection belongs to another Memory layer")


async def _resolve_sources(
    session: AsyncSession,
    view: MemoryReadView,
    selection: InterviewSourceSelection | SituationSourceSelection,
) -> dict[UUID, int | str]:
    if isinstance(selection, InterviewSourceSelection):
        if not selection.sequences:
            return {}
        messages = await interviews.read_interview_messages(
            session,
            InterviewReadScope(view.job_file_id, view.through_sequence),
            sequences=selection.sequences,
        )
        return {message.source_id: message.interview_sequence for message in messages}
    if not selection.titles:
        return {}
    entries = await read_queries.read_map(
        session,
        MemoryReadView(
            view.job_file_id, view.position_id, MemoryLayer.WORK_SITUATION, view.through_sequence
        ),
    )
    return {resolve_title(entries, title): title for title in selection.titles}


def _require_body_capacity(body: str, policy: BodyMatchPolicy) -> None:
    if len(body) > policy.max_body_characters:
        raise BodyEditError("patch_limit_exceeded", "Body exceeds the configured editing capacity")


def _update_preview(
    layer: MemoryLayer,
    before: MemoryContent,
    after: MemoryContent,
    added: tuple[int | str, ...],
    removed: tuple[int | str, ...],
) -> MemoryStatusPreview | MemoryUpdatePreview:
    if before == after and not added and not removed:
        return MemoryStatusPreview("unchanged")
    fields: list[Literal["title", "description"]] = []
    if before.title != after.title:
        fields.append("title")
    if before.description != after.description:
        fields.append("description")
    return MemoryUpdatePreview(
        after,
        tuple(fields),
        describe_body_change(before.body, after.body) if before.body != after.body else None,
        "interview_references"
        if layer == MemoryLayer.WORK_SITUATION
        else "work_situation_references",
        added,
        removed,
    )

apps/api/src/caliburn/workflows/public_t:
"""One bounded delivery mechanism for public text projections; no persistence."""

import asyncio
from collections.abc import Iterator
from contextlib import contextmanager
from uuid import UUID


class PublicStreamCapacityError(RuntimeError):
    """The bounded hub cannot admit another transient subscriber."""


class BoundedPublicTextHub[T]:
    def __init__(
        self,
        *,
        queue_capacity: int = 8,
        max_subscribers: int = 64,
        max_update_chars: int = 32768,
    ) -> None:
        if min(queue_capacity, max_subscribers, max_update_chars) < 1:
            raise ValueError("Public text hub limits must be positive")
        self._queue_capacity = queue_capacity
        self._max_subscribers = max_subscribers
        self._max_update_chars = max_update_chars
        self._loop: asyncio.AbstractEventLoop | None = None
        self._subscribers: dict[tuple[UUID, UUID], set[asyncio.Queue[T]]] = {}

    @contextmanager
    def subscribe(self, job_file_id: UUID, execution_id: UUID) -> Iterator[asyncio.Queue[T]]:
        self._check_loop()
        if sum(map(len, self._subscribers.values())) >= self._max_subscribers:
            raise PublicStreamCapacityError("Public text subscriber capacity reached")
        key = (job_file_id, execution_id)
        queue: asyncio.Queue[T] = asyncio.Queue(self._queue_capacity)
        self._subscribers.setdefault(key, set()).add(queue)
        try:
            yield queue
        finally:
            subscribers = self._subscribers[key]
            subscribers.remove(queue)
            if not subscribers:
                del self._subscribers[key]
            while not queue.empty():
                queue.get_nowait()

    def _publish(self, job_file_id: UUID, execution_id: UUID, update: T, chars: int) -> None:
        """Never await readers; overflow drops oldest, oversize drops whole updates.

        Callers supply only allowlisted accumulated text, not raw provider events.
        Durable history is read separately from native saved results.
        """
        subscribers = self._subscribers.get((job_file_id, execution_id))
        if not subscribers:
            return
        self._check_loop()
        if chars > self._max_update_chars:
            return
        for queue in subscribers:
            if queue.full():
                queue.get_nowait()
            queue.put_nowait(update)

    def _check_loop(self) -> None:
        loop = asyncio.get_running_loop()
        if self._loop is None:
            self._loop = loop
        elif self._loop is not loop:
            raise RuntimeError("Public text hub must be used on one event loop")

